/** The production experiment: every field is consumed by the game, then audited against preregistration. */
export interface ProgressionParameters {
  heroMinLevel: number;
  xpBase: number;
  xpGrowth: number;
  fieldHpNumerator: number;
  fieldHpDenominator: number;
  companionHpNumerator: number;
  companionHpDenominator: number;
  captureChance: number;
  firstCaptureBossIndex: number | null;
  heroLevelStepEvery: number;
  heroLevelStepCap: number;
  heroRestMs: number;
  heroDeferMs: number;
  xpRewardBase: number;
  xpRewardPerIndex: number;
  bossXpMultiplier: number;
  bossHpMultiplier: number;
}

/** Registered production control-l17; selecting a CLI ID does not change these values. */
export const PROGRESSION_PARAMETERS: Readonly<ProgressionParameters> = Object.freeze({
  heroMinLevel: 17,
  xpBase: 20,
  xpGrowth: 1.4,
  fieldHpNumerator: 115,
  fieldHpDenominator: 100,
  companionHpNumerator: 115,
  companionHpDenominator: 100,
  captureChance: 0.35,
  firstCaptureBossIndex: null,
  heroLevelStepEvery: 2,
  heroLevelStepCap: 6,
  heroRestMs: 120000,
  heroDeferMs: 30000,
  xpRewardBase: 5,
  xpRewardPerIndex: 3,
  bossXpMultiplier: 5,
  bossHpMultiplier: 5,
});

#!/usr/bin/env node
// Production reducer, deterministic modeled time. No Electron, network or player data.
import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, readdirSync, realpathSync, renameSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual, parseArgs } from 'node:util';
import { Worker } from 'node:worker_threads';
import { CONFIG, PROTOCOL_PATH, validateProtocol } from './config.mjs';
import { ROOT, sourceDigest, evaluationDigest, sha256 } from './evidence.mjs';

const fail = (message) => { throw new Error(message); };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const integer = (n, min = 0, max = Number.MAX_SAFE_INTEGER) => Number.isSafeInteger(n) && n >= min && n <= max;
const decimal = (s) => typeof s === 'string' && /^(?:0|-?[1-9]\d*)$/.test(s);
const digest = (s) => typeof s === 'string' && /^[a-f0-9]{64}$/.test(s);
const firstNames = ['firstKillSec', 'firstRewardSec', 'firstLevelSec', 'firstCaptureSec', 'firstReadySec', 'firstOpenSec', 'firstAcceptedSec'];
const contentKinds = ['eligibleHero', 'eligibleMonster', 'seenHero', 'seenMonster', 'chosenHero', 'killedMonster', 'capturedMonster'];
const bigintMetrics = ['heroDamage', 'companionDamage', 'partyPower'];
const numberMetrics = ['level', 'kills', 'coins', 'income', 'spent', 'companions', 'maxCompanionLevel', 'reincarnations',
  'training', 'offers', 'rerolls', 'managementActions', 'feverStarts', 'inputCount', 'longestKillGapSec',
  'longestMeaningfulGapSec', 'longestDiscoveryGapSec', 'lastUnlockSec', ...firstNames,
  ...contentKinds.map((kind) => `${kind}Count`)];

const registeredContentRules = (protocol) => Object.fromEntries(protocol.milestones.flatMap((milestone) =>
  milestone.ids.map((id) => [id, milestone.requirements])));

/** Only the official registration may authorize new candidate/validation seed execution. */
export function readMeasurementProtocol(path, phase) {
  if (phase !== 'baseline' && realpathSync(path) !== realpathSync(PROTOCOL_PATH)) fail('Candidate/release must use the official registered protocol path.');
  return JSON.parse(readFileSync(phase === 'baseline' ? path : PROTOCOL_PATH, 'utf8'));
}

/** Live execution/acceptance is stricter than historical, embedded-protocol comparisons. */
export function validateOfficialProtocolSnapshot(protocol, protocolSha256 = sha256(JSON.stringify(protocol))) {
  const official = JSON.parse(readFileSync(PROTOCOL_PATH, 'utf8'));
  if (sha256(JSON.stringify(protocol)) !== protocolSha256 || protocolSha256 !== sha256(JSON.stringify(official))) fail('Measurement snapshot differs from the current official registered protocol.');
}

/** Select a preregistered build, never change production behavior from the measurement CLI. */
export function selectExperiment(protocol, options, phase, seedSet) {
  const candidate = options.candidate, control = options.control;
  if (candidate !== undefined && control !== undefined) fail('--candidate and --control are mutually exclusive.');
  if (phase === 'baseline') {
    if (candidate !== undefined || control !== undefined) fail('Baseline does not select a candidate or control.');
    if (protocol.schemaVersion !== 1 || protocol.phase !== 'baseline') fail('Baseline requires its preserved schemaVersion 1 baseline protocol.');
    return null;
  }
  if (protocol.schemaVersion !== 2) fail('New candidate/release measurements require a schemaVersion 2 protocol.');
  if (protocol.experimentStage !== seedSet || !['exploration', 'validation'].includes(seedSet)) fail('Experiment stage must match the exploration or validation seed set.');
  if (phase === 'release' && seedSet !== 'validation') fail('Release requires the frozen validation experiment.');
  const selected = candidate !== undefined ? { kind: 'candidate', id: candidate }
    : control !== undefined ? { kind: 'control', id: control } : protocol.experimentStage === 'validation' ? protocol.selectedExperiment : null;
  if (!selected || !['candidate', 'control'].includes(selected.kind) || typeof selected.id !== 'string' || !selected.id) fail('Exploration requires an explicit --candidate ID or --control ID; validation requires a frozen selection.');
  const entry = protocol[selected.kind === 'candidate' ? 'candidates' : 'controls'].find((entry) => entry.id === selected.id);
  if (!entry) fail('Experiment ID is not registered in this protocol.');
  if (seedSet === 'validation' && !isDeepStrictEqual(selected, protocol.selectedExperiment)) fail('Validation/release may only measure the frozen selected experiment.');
  return { ...selected, parametersSha256: sha256(JSON.stringify(entry.parameters)),
    contentRulesSha256: sha256(JSON.stringify(registeredContentRules(protocol))) };
}

/** The build must export the values consumed by its actual formulas and content selectors. */
export function validateProductionExperiment(core, protocol, experiment) {
  const entry = protocol[experiment.kind === 'candidate' ? 'candidates' : 'controls'].find((entry) => entry.id === experiment.id);
  if (!entry || !isDeepStrictEqual(core.PROGRESSION_PARAMETERS, entry.parameters)) fail('Production PROGRESSION_PARAMETERS differ from the registered experiment.');
  const rules = registeredContentRules(protocol);
  const production = Object.fromEntries(Object.keys(rules).map((id) => [id,
    core.PROGRESSION_CONTENT_RULES && Object.hasOwn(core.PROGRESSION_CONTENT_RULES, id) ? core.PROGRESSION_CONTENT_RULES[id] : undefined]));
  if (!isDeepStrictEqual(production, rules)) fail('Production PROGRESSION_CONTENT_RULES differ from the registered milestones.');
}

function validateExperimentEvidence(report) {
  if (report.protocol.schemaVersion !== 2) return;
  const selected = report.experiment;
  if (!selected || !['candidate', 'control'].includes(selected.kind)) fail('Missing experiment identity.');
  const expected = selectExperiment(report.protocol, { [selected.kind]: selected.id }, report.phase, report.seedSet);
  if (!isDeepStrictEqual(selected, expected)) fail('Experiment identity or parameter/content fingerprint mismatch.');
}

/** Conditional quantiles are accompanied by their full, uncensored denominator. */
export function distribution(values) {
  if (!Array.isArray(values) || values.some((v) => v !== null && (typeof v !== 'number' || !Number.isFinite(v)))) fail('Non-finite measured value.');
  const sorted = values.filter((v) => v !== null).sort((a, b) => a - b);
  const at = (q) => sorted.length ? sorted[Math.floor((sorted.length - 1) * q)] : null;
  return { samples: values.length, reached: sorted.length, unreached: values.length - sorted.length,
    p10: at(.1), p50: at(.5), p90: at(.9), min: at(0), max: at(1) };
}

export function bigintDistribution(values) {
  if (values.some((v) => !decimal(v))) fail('Invalid exact bigint.');
  const sorted = [...values].sort((a, b) => BigInt(a) < BigInt(b) ? -1 : BigInt(a) > BigInt(b) ? 1 : 0);
  const at = (q) => sorted.length ? sorted[Math.floor((sorted.length - 1) * q)] : null;
  return { samples: values.length, p10: at(.1), p50: at(.5), p90: at(.9), min: at(0), max: at(1) };
}

/** Non-reachers sort after reached times: never pass a median using survivors only. */
export function populationQuantile(values, q) {
  distribution(values);
  const sorted = [...values].sort((a, b) => (a ?? Infinity) - (b ?? Infinity));
  return sorted.length ? sorted[Math.floor((sorted.length - 1) * q)] : null;
}

function validatePolicy(policy, settings) {
  for (const [field, allowed] of [['profile', settings.profiles], ['policy', settings.policies],
    ['inputSchedule', settings.inputSchedules], ['management', settings.managementPolicies], ['menuVisitSeconds', settings.menuVisitSeconds]]) {
    if (!allowed.includes(policy[field])) fail(`Unknown ${field}: ${String(policy[field])}`);
  }
  return policy;
}
const policyKey = (p) => [p.profile, p.policy, p.inputSchedule, p.management, p.menuVisitSeconds].join('/');

function validateSettings(settings) {
  if (!integer(settings.tickMs, 1, 100) || 1000 % settings.tickMs !== 0 ||
    !integer(settings.observationMs, settings.tickMs) || settings.observationMs % settings.tickMs !== 0) fail('Invalid measurement clock.');
  const cps = settings.checkpointsMinutes;
  if (!Array.isArray(cps) || !cps.length || cps.some((m, i) => !integer(m, 1, 720) || i > 0 && m <= cps[i - 1])) fail('Checkpoints must increase within 1..720 minutes.');
}

export function observationSettings(settings, screening = false) {
  if (!screening) return settings;
  if (!integer(settings.explorationHorizonMinutes, 1, settings.checkpointsMinutes.at(-1))) fail('Invalid exploration horizon.');
  return { ...settings, checkpointsMinutes: settings.checkpointsMinutes.filter((m) => m <= settings.explorationHorizonMinutes) };
}

const emptyFirst = () => Object.fromEntries(firstNames.map((name) => [name, null]));
const mapOf = (records, kind, sec = Infinity) => Object.fromEntries(records.filter((r) => r.kind === kind && r.sec <= sec).map((r) => [r.id, r.sec]));
function firstFromRecords(records, sec = Infinity) {
  const first = emptyFirst();
  for (const r of records) if (r.sec <= sec && firstNames.includes(r.kind)) first[r.kind] = r.sec;
  return first;
}
function unlockTime(records, milestones, sec = Infinity) {
  const finals = milestones.filter((m) => m.final);
  if (!finals.length) return null;
  const times = finals.flatMap((m) => {
    const eligible = mapOf(records, m.kind === 'hero' ? 'eligibleHero' : 'eligibleMonster', sec);
    return m.ids.map((id) => eligible[id] ?? null);
  });
  return times.includes(null) ? null : Math.max(...times);
}

/** Read general-hero eligibility from the production save validator, never duplicate its rank formula. */
export function eligibleContent(core, state, cache = {}) {
  if (core.eligibleHeroIds && core.eligibleMonsterIds) return { heroes: core.eligibleHeroIds(state), monsters: core.eligibleMonsterIds(state) };
  const context = core.discoveryContext(state, core.heroForm(state.hero?.equipped.formId ?? '')?.type);
  const hero = state.hero ?? core.newHeroProgress();
  const cacheKey = hero.reincarnations;
  if (cache.key !== cacheKey) {
    cache.key = cacheKey;
    cache.standard = core.STANDARD_HERO_FORMS.filter((form) => {
      const others = core.STANDARD_HERO_FORMS.filter((f) => f.rank === 1 && f.type !== form.type)
        .filter((f, i, all) => all.findIndex((x) => x.type === f.type) === i).slice(0, 2);
      if (others.length !== 2) fail('Production eligibility adapter needs two distinct introductory hero elements.');
      const choices = [form, ...others].map((f) => ({ formId: f.id, buffPercent: core.HERO_BUFF_MIN }));
      const parsed = core.parseHeroProgress({ ...hero, choices, deferRemainingMs: 0, restRemainingMs: 0 }, context);
      return parsed?.choices.some((c) => c.formId === form.id);
    }).map((f) => f.id);
  }
  // v0.7 can expose the same production selectors used by spawning/offers. The v0.6 adapter is explicit in evidence.
  const heroes = core.eligibleHeroIds ? core.eligibleHeroIds(state) : [...cache.standard,
    ...core.RARE_HERO_FORMS.filter((f) => core.requirementsMet(f.requirements, context)).map((f) => f.id)];
  const monsters = core.eligibleMonsterIds ? core.eligibleMonsterIds(state) : [...core.COMMON_SPECIES_IDS,
    ...core.RARE_MONSTERS.filter((f) => core.requirementsMet(f.requirements, context)).map((f) => f.id)];
  return { heroes, monsters };
}

function manage(core, engine, mode) {
  const state = engine.getState();
  const cs = [...state.companions].sort((a, b) => a.id.localeCompare(b.id, 'en'));
  let action;
  if (mode === 'consume-weakest' && cs.length >= 2) {
    cs.sort((a, b) => core.companionPower(a) < core.companionPower(b) ? -1 : core.companionPower(a) > core.companionPower(b) ? 1 : a.id.localeCompare(b.id, 'en'));
    action = { type: 'consume', targetId: cs.at(-1).id, foodId: cs[0].id };
  } else if (mode === 'fuse-first') {
    for (let i = 0; i < cs.length && !action; i++) {
      const other = cs.slice(i + 1).find((c) => c.speciesId === cs[i].speciesId && c.stars === cs[i].stars);
      if (other) action = { type: 'fuse', aId: cs[i].id, bId: other.id };
    }
  } else if (mode === 'reincarnate-first') {
    const c = cs.find((c) => !('error' in core.applyCollection(state, { type: 'reincarnate', id: c.id })));
    if (c) action = { type: 'reincarnate', id: c.id };
    else return manage(core, engine, 'consume-weakest');
  }
  if (!action || 'error' in core.applyCollection(state, action)) return null;
  const events = engine.apply(action);
  return { action, events };
}

function inputDue(ms, policy) {
  if (policy.profile === 'pure-idle') return false;
  const minuteMs = (ms - 1) % 60_000;
  const active = ms <= 120_000 || policy.profile === 'active' || policy.profile === 'intermittent' && minuteMs < 15_000;
  if (!active) return false;
  if (policy.inputSchedule === 'uniform') return ms % 500 === 0;
  // Six 20-input bursts/minute. Intermittent's second burst is 10 hits: 30 inputs per 15s active window.
  const hits = policy.profile === 'intermittent' && ms > 120_000 && minuteMs >= 10_000 ? 10 : 20;
  return (ms - 1) % 10_000 < hits * 100 && ms % 100 === 0;
}

export function simulate(core, policy, seed, options = {}) {
  const settings = options.settings ?? CONFIG.measurement;
  validateSettings(settings); validatePolicy(policy, settings);
  if (!integer(seed, 0, 0xffffffff)) fail('Seed must be uint32.');
  const milestones = options.milestones ?? [];
  const fixture = options.fixture ?? null;
  const engine = core.createEngine(fixture, core.mulberry32(seed));
  const start = engine.getState();
  const initial = { coins: start.coins, goldSpent: start.progress?.goldSpent ?? 0, kills: start.killCount,
    reincarnations: start.hero?.reincarnations ?? 0, playTimeSec: (start.progress?.playTimeMs ?? 0) / 1000 };
  const records = [], checkpoints = [], actions = [];
  const recorded = new Set(), eligibilityCache = {};
  let ms = 0, income = 0, heroDamage = 0n, companionDamage = 0n, inputCount = 0, offers = 0, rerolls = 0, managementActions = 0, feverStarts = 0;
  let lastKill = 0, lastMeaningful = 0, lastDiscovery = 0, killGap = 0, meaningfulGap = 0, discoveryGap = 0;
  let readyState = start, readyAt = 0, currentLevel = start.level;
  const refresh = () => { readyState = engine.getState(); readyAt = ms; currentLevel = readyState.level; return readyState; };
  const meaningful = () => { meaningfulGap = Math.max(meaningfulGap, ms - lastMeaningful); lastMeaningful = ms; };
  const record = (kind, id = '') => {
    const key = `${kind}/${id}`;
    if (recorded.has(key)) return;
    recorded.add(key); records.push({ kind, id, sec: ms / 1000 });
    if (kind === 'seenHero' || kind === 'seenMonster') {
      discoveryGap = Math.max(discoveryGap, ms - lastDiscovery); lastDiscovery = ms; meaningful();
    }
  };
  const observe = (events) => {
    let eligibilityChanged = false;
    for (const event of events) {
      if (event.type === 'attack') heroDamage += event.damage;
      if (event.type === 'companionAttack') companionDamage += event.damage;
      if (event.type === 'feverStart') feverStarts++;
      if (event.type === 'itemDropped') {
        record('firstRewardSec');
        income += event.drops.reduce((sum, drop) => sum + (drop.item.kind === 'coin' ? drop.amount : 0), 0);
      }
      if (event.type === 'monsterKilled') {
        eligibilityChanged = true;
        record('firstKillSec'); record('killedMonster', event.monster.speciesId);
        killGap = Math.max(killGap, ms - lastKill); lastKill = ms;
      }
      if (event.type === 'levelUp') { eligibilityChanged = true; currentLevel = event.newLevel; record('firstLevelSec'); meaningful(); }
      if (event.type === 'bossCaptured') { eligibilityChanged = true; record('firstCaptureSec'); record('capturedMonster', event.companion.speciesId); meaningful(); }
      if (event.type === 'heroReady') eligibilityChanged = true;
      if (event.type === 'monsterSpawned') record('seenMonster', event.monster.speciesId);
    }
    // Observe the production state before the next action can reset its level or consume its roster.
    if (eligibilityChanged) content(engine.getState());
  };
  const ready = () => {
    const hero = readyState.hero && { ...readyState.hero,
      restRemainingMs: Math.max(0, (readyState.hero.restRemainingMs ?? 0) - (ms - readyAt)),
      deferRemainingMs: Math.max(0, (readyState.hero.deferRemainingMs ?? 0) - (ms - readyAt)) };
    return core.heroReady(currentLevel, hero);
  };
  const content = (state) => {
    const eligible = eligibleContent(core, state, eligibilityCache);
    for (const id of eligible.heroes) record('eligibleHero', id);
    for (const id of eligible.monsters) record('eligibleMonster', id);
    for (const id of state.progress?.seenHeroes ?? []) record('seenHero', id);
    for (const id of state.progress?.seenMonsters ?? []) record('seenMonster', id);
    for (const hero of state.hero?.collection ?? []) record('chosenHero', hero.formId);
  };
  content(start);
  if (ready()) record('firstReadySec');
  const end = settings.checkpointsMinutes.at(-1) * 60_000;
  for (ms = settings.tickMs; ms <= end; ms += settings.tickMs) {
    observe(engine.tick(settings.tickMs));
    if (inputDue(ms, policy)) { observe(engine.attack('keyboard')); inputCount++; }
    const isReady = ready();
    if (isReady) record('firstReadySec');
    const visit = policy.menuVisitSeconds === 0 || ms % (policy.menuVisitSeconds * 1000) === 0;
    if (visit && isReady) {
      let state = refresh();
      content(state);
      if (!state.hero?.choices.length) { observe(engine.apply({ type: 'heroOffer' })); state = refresh(); }
      if (state.hero?.choices.length === 3) {
        record('firstOpenSec'); offers++;
        for (const choice of state.hero.choices) record('seenHero', choice.formId);
        if (policy.policy === 'reroll') {
          content(state);
          const before = state.hero.offerSerial;
          observe(engine.apply({ type: 'heroReroll', offerSerial: before })); state = refresh();
          if (state.hero.offerSerial !== before) rerolls++;
          for (const choice of state.hero.choices) record('seenHero', choice.formId);
        }
        const before = state.hero.reincarnations, choice = state.hero.choices[0], level = state.level;
        content(state);
        observe(engine.apply({ type: 'heroChoose', formId: choice.formId, offerSerial: state.hero.offerSerial }));
        state = refresh();
        if (state.hero.reincarnations !== before + 1) fail('Production hero choice did not complete.');
        record('firstAcceptedSec'); record('chosenHero', choice.formId); meaningful();
        actions.push({ type: 'heroChoose', sec: ms / 1000, formId: choice.formId, level });
        content(state);
      }
    }
    if (ms % settings.observationMs !== 0) continue;
    if (visit && policy.management !== 'none') {
      content(engine.getState());
      const result = manage(core, engine, policy.management);
      if (result) { observe(result.events); managementActions++; actions.push({ ...result.action, sec: ms / 1000 }); }
    }
    if (visit && ['training', 'lure'].includes(policy.policy)) {
      const state = engine.getState();
      content(state);
      observe(engine.apply({ type: 'shopBuy', item: policy.policy, shopSerial: state.progress.shopSerial }));
    }
    const state = refresh(); content(state);
    const spent = state.progress.goldSpent - initial.goldSpent;
    if (!integer(income) || !integer(spent) || !integer(state.coins) || initial.coins + income - spent !== state.coins) fail('Gold conservation failed.');
    if (!settings.checkpointsMinutes.includes(ms / 60_000)) continue;
    const sec = ms / 1000;
    checkpoints.push({ minutes: ms / 60_000, level: state.level, kills: state.killCount - initial.kills,
      coins: state.coins, income, spent, companions: state.companions.length,
      maxCompanionLevel: Math.max(0, ...state.companions.map((c) => c.level)),
      reincarnations: (state.hero?.reincarnations ?? 0) - initial.reincarnations, training: state.progress.trainingLevel,
      offers, rerolls, managementActions, feverStarts, inputCount, heroDamage: String(heroDamage), companionDamage: String(companionDamage),
      partyPower: String(core.activeCompanions(state.companions, state.monster.type, state.hero?.equipped)
        .reduce((sum, c) => sum + core.companionPower(c), 0n)),
      longestKillGapSec: Math.max(killGap, ms - lastKill) / 1000,
      longestMeaningfulGapSec: Math.max(meaningfulGap, ms - lastMeaningful) / 1000,
      longestDiscoveryGapSec: Math.max(discoveryGap, ms - lastDiscovery) / 1000,
      ...firstFromRecords(records), lastUnlockSec: unlockTime(records, milestones),
      ...Object.fromEntries(contentKinds.map((kind) => [`${kind}Count`, Object.keys(mapOf(records, kind, sec)).length])) });
  }
  return { policy, seed, initial, records, actions, checkpoints };
}

export function summarize(runs) {
  const groups = new Map();
  for (const run of runs) for (const row of run.checkpoints) {
    const key = `${policyKey(run.policy)}/${row.minutes}`;
    const group = groups.get(key) ?? { policy: run.policy, minutes: row.minutes, rows: [] };
    group.rows.push(row); groups.set(key, group);
  }
  return [...groups.values()].sort((a, b) => `${policyKey(a.policy)}/${a.minutes}`.localeCompare(`${policyKey(b.policy)}/${b.minutes}`, 'en'))
    .map(({ policy, minutes, rows }) => ({ policy, minutes, samples: rows.length,
      metrics: { ...Object.fromEntries(numberMetrics.map((metric) => [metric, distribution(rows.map((r) => r[metric]))])),
        ...Object.fromEntries(bigintMetrics.map((metric) => [metric, bigintDistribution(rows.map((r) => r[metric]))])) } }));
}

export function evaluateTargets(runs, settings, milestones, screening = false) {
  const canonical = runs.filter((r) => same(r.policy, settings.baseline));
  if (!canonical.length) return { status: 'NOT_EVALUATED', passed: null, samples: 0, checks: [],
    method: 'This experiment contains no canonical continuous-active free-policy run; no v0.7 target claim is made.' };
  const times = canonical.map((r) => r.checkpoints.at(-1).firstAcceptedSec);
  const target = settings.targets.firstReincarnation;
  const median = populationQuantile(times, .5);
  const reachedBeforeDeadline = times.filter((t) => t !== null && t <= target.deadlineSec).length;
  const finalTimes = canonical.map((r) => unlockTime(r.records, milestones));
  const lastMedian = populationQuantile(finalTimes, .5), last = settings.targets.lastUnlock;
  const checks = [
    { id: 'first-reincarnation-median', passed: median !== null && median >= target.medianMinSec && median <= target.medianMaxSec,
      observedSec: median, minSec: target.medianMinSec, maxSec: target.medianMaxSec },
    { id: 'first-reincarnation-deadline', passed: times.length > 0 && reachedBeforeDeadline / times.length >= target.minimumReachedFraction,
      reached: reachedBeforeDeadline, samples: times.length, deadlineSec: target.deadlineSec, minimumFraction: target.minimumReachedFraction },
    { id: 'last-unlock-median', passed: milestones.some((m) => m.final) && lastMedian !== null && lastMedian >= last.medianMinSec && lastMedian <= last.medianMaxSec,
      observedSec: lastMedian, minSec: last.medianMinSec, maxSec: last.medianMaxSec, registered: milestones.some((m) => m.final) },
  ];
  if (screening) checks.pop();
  return { status: checks.every((c) => c.passed) ? 'PASS' : 'FAIL', passed: checks.every((c) => c.passed), samples: canonical.length, checks,
    skipped: screening ? ['last-unlock-median: NOT_EVALUATED in 120-minute exploration screening'] : [],
    method: 'Population median sorts unreached after all observed times; deadline fraction always divides by all samples.' };
}

function validateMilestones(milestones, catalog) {
  if (!Array.isArray(milestones)) fail('Missing milestone registry.');
  const seen = new Set();
  for (const m of milestones) {
    if (!m || typeof m.id !== 'string' || !m.id || seen.has(m.id) || typeof m.label !== 'string' || !['hero', 'monster'].includes(m.kind) ||
      typeof m.final !== 'boolean' || !Array.isArray(m.ids) || !m.ids.length || new Set(m.ids).size !== m.ids.length ||
      m.ids.some((id) => !catalog[m.kind].includes(id))) fail('Invalid milestone registry.');
    seen.add(m.id);
  }
}

export function validateRun(run, settings, milestones, catalog) {
  validatePolicy(run.policy, settings);
  if (!integer(run.seed, 0, 0xffffffff) || !run.initial || Object.values(run.initial).some((n) => typeof n !== 'number' || !Number.isFinite(n) || n < 0)) fail('Invalid raw run.');
  if (!Array.isArray(run.records) || !Array.isArray(run.actions) || !Array.isArray(run.checkpoints) ||
    !same(run.checkpoints.map((r) => r.minutes), settings.checkpointsMinutes)) fail('Missing or duplicate checkpoints.');
  let actionSec = -1;
  for (const action of run.actions) {
    if (!['heroChoose', 'consume', 'fuse', 'reincarnate'].includes(action.type) || typeof action.sec !== 'number' || !Number.isFinite(action.sec) ||
      action.sec < actionSec || action.sec < 0 || action.sec > settings.checkpointsMinutes.at(-1) * 60 ||
      action.type === 'heroChoose' && (!catalog.hero.includes(action.formId) || !integer(action.level, 1))) fail('Invalid action ledger.');
    actionSec = action.sec;
  }
  const seen = new Set(); let previousSec = -1;
  for (const r of run.records) {
    const key = `${r.kind}/${r.id}`;
    if (![...firstNames, ...contentKinds].includes(r.kind) || seen.has(key) || typeof r.sec !== 'number' || !Number.isFinite(r.sec) ||
      r.sec < previousSec || r.sec > settings.checkpointsMinutes.at(-1) * 60 || r.sec < 0 ||
      firstNames.includes(r.kind) && r.id !== '' || contentKinds.includes(r.kind) && !catalog[r.kind.endsWith('Hero') ? 'hero' : 'monster'].includes(r.id)) fail('Invalid, duplicate or out-of-order first record.');
    seen.add(key); previousSec = r.sec;
  }
  let previous = null;
  for (const row of run.checkpoints) {
    const sec = row.minutes * 60;
    for (const metric of numberMetrics) {
      const nullable = firstNames.includes(metric) || metric === 'lastUnlockSec';
      if (!(nullable && row[metric] === null) && (typeof row[metric] !== 'number' || !Number.isFinite(row[metric]) || row[metric] < 0)) fail(`Invalid ${metric}.`);
    }
    for (const metric of ['level', 'kills', 'coins', 'income', 'spent', 'companions', 'maxCompanionLevel', 'reincarnations', 'training', 'offers', 'rerolls', 'managementActions', 'feverStarts', 'inputCount']) {
      if (!integer(row[metric], metric === 'level' ? 1 : 0)) fail('Invalid integer checkpoint.');
    }
    for (const metric of bigintMetrics) if (!decimal(row[metric]) || BigInt(row[metric]) < 0n) fail('Invalid bigint checkpoint.');
    if (run.initial.coins + row.income - row.spent !== row.coins) fail('Gold conservation failed.');
    const first = firstFromRecords(run.records, sec);
    if (firstNames.some((name) => first[name] !== row[name]) || row.lastUnlockSec !== unlockTime(run.records, milestones, sec)) fail('First records or milestone timing disagree.');
    if (first.firstOpenSec !== null && (first.firstReadySec === null || first.firstOpenSec < first.firstReadySec) ||
      first.firstAcceptedSec !== null && (first.firstOpenSec === null || first.firstAcceptedSec < first.firstOpenSec)) fail('Invalid readiness/open/accept order.');
    for (const kind of contentKinds) if (row[`${kind}Count`] !== Object.keys(mapOf(run.records, kind, sec)).length) fail('Content count disagrees with first records.');
    const accepted = run.actions.filter((a) => a.type === 'heroChoose' && a.sec <= sec);
    if (row.reincarnations !== accepted.length || row.offers !== accepted.length || row.rerolls > row.offers ||
      (accepted[0]?.sec ?? null) !== row.firstAcceptedSec) fail('Reincarnation action ledger mismatch.');
    if (row.managementActions !== run.actions.filter((a) => a.type !== 'heroChoose' && a.sec <= sec).length) fail('Management action ledger mismatch.');
    for (const metric of ['longestKillGapSec', 'longestMeaningfulGapSec', 'longestDiscoveryGapSec']) if (row[metric] > sec) fail('Gap exceeds observation duration.');
    if (previous) {
      for (const key of ['kills', 'income', 'spent', 'inputCount', 'reincarnations', 'offers', 'feverStarts']) if (row[key] < previous[key]) fail('Cumulative counter decreased.');
      for (const key of ['heroDamage', 'companionDamage']) if (BigInt(row[key]) < BigInt(previous[key])) fail('Cumulative damage decreased.');
    }
    previous = row;
  }
  return run;
}

export function validateMeasurement(report, expectedSourceDigest, expectedEvaluationDigest) {
  if (report?.version !== 7 || report.kind !== 'simulated-engine-measurement' || !CONFIG.phases.includes(report.phase) || report.phase === 'setup' ||
    report.rawComplete !== true || !digest(report.sourceDigest) || !digest(report.evaluationDigest) || !digest(report.fixtureSha256) ||
    expectedSourceDigest !== undefined && report.sourceDigest !== expectedSourceDigest || expectedEvaluationDigest !== undefined && report.evaluationDigest !== expectedEvaluationDigest) fail('Invalid or stale measurement provenance.');
  validateSettings(report.settings);
  if (report.screening && (report.phase !== 'candidate' || report.seedSet !== 'exploration')) fail('Screening requires candidate phase and exploration seeds.');
  const observedSettings = observationSettings(report.settings, report.screening === true);
  if (!same(report.checkpointsMinutes, observedSettings.checkpointsMinutes)) fail('Declared observation horizon disagrees with the frozen mode.');
  validateProtocol(report.protocol, report.phase !== 'baseline');
  validateExperimentEvidence(report);
  if (!same(report.settings, CONFIG.measurement)) fail('Measurement settings differ from frozen configuration.');
  if (sha256(JSON.stringify(report.protocol)) !== report.protocolSha256 || sha256(JSON.stringify(report.runs)) !== report.rawSha256 ||
    sha256(JSON.stringify(report.fixture)) !== report.fixtureSha256 || report.fixture !== null) fail('Measurement content fingerprint mismatch or non-fresh canonical fixture.');
  if (!report.build || !digest(report.build.sha256) || sha256(JSON.stringify(report.build.files)) !== report.build.sha256 ||
    !Object.keys(report.build.files ?? {}).length || Object.values(report.build.files).some((hash) => !digest(hash))) fail('Invalid compiled build provenance.');
  if (!report.catalog || !['hero', 'monster'].every((kind) => Array.isArray(report.catalog[kind]) && report.catalog[kind].length > 0 && new Set(report.catalog[kind]).size === report.catalog[kind].length)) fail('Invalid content catalog.');
  const milestones = report.protocol.milestones;
  validateMilestones(milestones, report.catalog);
  if (report.phase !== 'baseline' && !milestones.some((m) => m.final)) fail('Candidate measurement requires final unlock milestones.');
  const declared = report.settings.seeds[report.seedSet];
  if (!declared || !same(report.seeds, declared) || !Array.isArray(report.policies) || report.policies.length < 1 ||
    new Set(report.policies.map(policyKey)).size !== report.policies.length) fail('Invalid seed or policy registry.');
  if (report.phase === 'baseline' && report.seedSet !== 'baseline' || report.phase === 'release' && report.seedSet !== 'validation') fail('Phase uses an invalid seed set.');
  if (report.phase === 'release' && !same(report.policies, report.settings.validationPolicies)) fail('Release requires the full registered validation policy suite.');
  const expected = new Set(report.policies.flatMap((p) => Array.from({ length: declared.count }, (_, i) => `${policyKey(p)}/${declared.start + i}`)));
  if (!Array.isArray(report.runs)) fail('Missing raw runs.');
  for (const run of report.runs) {
    const key = `${policyKey(run.policy)}/${run.seed}`;
    if (!expected.delete(key)) fail('Duplicate or unexpected seed/policy run.');
    validateRun(run, observedSettings, milestones, report.catalog);
    if (Object.values(run.initial).some((n) => n !== 0)) fail('Canonical fresh fixture has nonzero initial progress.');
  }
  if (expected.size) fail('Missing seed/policy runs.');
  if (!same(report.scenarios, summarize(report.runs))) fail('Summary differs from raw runs.');
  if (!same(report.targets, evaluateTargets(report.runs, report.settings, milestones, report.screening === true))) fail('Target verdict differs from raw runs.');
  return report;
}

/** Task acceptance is stricter than structurally valid evidence for an exploratory experiment. */
export function validateMeasurementPhase(report, phase, expectedSourceDigest, expectedEvaluationDigest) {
  if (!['baseline', 'candidate', 'release'].includes(phase)) fail('Unknown measurement acceptance phase.');
  validateMeasurement(report, expectedSourceDigest, expectedEvaluationDigest);
  if (report.phase !== phase) fail(`Expected ${phase} measurement, received ${report.phase}.`);
  if (report.screening || !same(report.checkpointsMinutes, CONFIG.measurement.checkpointsMinutes)) fail('Phase acceptance requires the full 12-hour observation horizon.');
  if (phase === 'baseline') {
    if (report.seedSet !== 'baseline' || !same(report.seeds, CONFIG.measurement.seeds.baseline) ||
      !same(report.policies, [CONFIG.measurement.baseline])) fail('Baseline acceptance requires exactly the canonical baseline policy and baseline seed set.');
  } else {
    if (report.seedSet !== 'validation' || !same(report.seeds, CONFIG.measurement.seeds.validation)) fail('Candidate/release acceptance requires the full validation seed set.');
    if (!report.policies.some((policy) => same(policy, CONFIG.measurement.baseline))) fail('Candidate/release acceptance requires the canonical baseline policy.');
    if (phase === 'release' && !same(report.policies, CONFIG.measurement.validationPolicies)) fail('Release acceptance requires the full registered validation policy suite.');
    if (report.targets.passed !== true) fail('Candidate/release acceptance requires every registered target to pass.');
  }
  return report;
}

export function compareMeasurements(before, after) {
  validateMeasurement(before); validateMeasurement(after);
  if (before.fixtureSha256 !== after.fixtureSha256 ||
    !same(before.settings, after.settings) || !same(before.checkpointsMinutes, after.checkpointsMinutes) ||
    !same(before.seeds, after.seeds) || !same(before.policies, after.policies)) fail('Comparison requires identical settings, horizon, fixture, seeds and policies.');
  const comparableMilestones = same(before.protocol.milestones, after.protocol.milestones);
  const previous = new Map(before.runs.map((r) => [`${policyKey(r.policy)}/${r.seed}`, r]));
  const deltas = after.runs.map((run) => {
    const base = previous.get(`${policyKey(run.policy)}/${run.seed}`);
    return { policy: run.policy, seed: run.seed, checkpoints: run.checkpoints.map((row, i) => ({ minutes: row.minutes,
      ...Object.fromEntries(numberMetrics.map((key) => [key, row[key] === null || base.checkpoints[i][key] === null || key === 'lastUnlockSec' && !comparableMilestones ? null : row[key] - base.checkpoints[i][key]])),
      ...Object.fromEntries(bigintMetrics.map((key) => [key, String(BigInt(row[key]) - BigInt(base.checkpoints[i][key]))])) })) };
  });
  return { version: 7, kind: 'paired-measurement-comparison', beforeSourceDigest: before.sourceDigest, afterSourceDigest: after.sourceDigest,
    beforeProtocolSha256: before.protocolSha256, afterProtocolSha256: after.protocolSha256, comparableMilestones, rawDeltas: deltas, scenarios: summarize(deltas),
    ...(before.experiment ? { beforeExperiment: before.experiment } : {}), ...(after.experiment ? { afterExperiment: after.experiment } : {}),
    method: 'Subtract the same seed/policy/checkpoint before aggregating. Source versions may differ; null pairs remain censored.' };
}

function writeAtomic(path, value) {
  mkdirSync(dirname(path), { recursive: true });
  const temporary = `${path}.tmp`;
  writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`); renameSync(temporary, path);
}

/** Build is run by the host, with source stability checked before loading production modules. */
function buildProduction() {
  const source = sourceDigest();
  const result = spawnSync('npm', ['run', 'build'], { cwd: ROOT, encoding: 'utf8' });
  if (result.status !== 0) fail(`Production build failed: ${result.stderr || result.stdout || result.error}`);
  if (sourceDigest() !== source) fail('Source changed during production build.');
  const files = readdirSync(resolve(ROOT, 'src/core'), { recursive: true }).filter((n) => n.endsWith('.ts')).sort();
  const hashes = {};
  for (const name of files) {
    const src = resolve(ROOT, 'src/core', name), built = resolve(ROOT, 'dist/electron/core', name.replace(/\.ts$/, '.js'));
    if (statSync(built).mtimeMs < statSync(src).mtimeMs) fail('Production build is stale.');
    hashes[relative(ROOT, built)] = sha256(readFileSync(built));
  }
  return { sourceDigest: source, build: { command: 'npm run build', files: hashes, sha256: sha256(JSON.stringify(hashes)) } };
}

function verifyBuild(build) {
  const files = Object.fromEntries(Object.keys(build.files).map((name) => [name, sha256(readFileSync(resolve(ROOT, name)))]));
  if (sha256(JSON.stringify(files)) !== build.sha256) fail('Compiled production build changed during measurement.');
}

/** Each worker processes one seed at a time. Only the host writes evidence. */
export function workerSimulation(worker, task) {
  return new Promise((resolveTask, rejectTask) => {
    const clear = () => { worker.off('message', message); worker.off('error', error); worker.off('exit', exited); };
    const message = (result) => { clear(); if (result.ok) resolveTask(result.run); else rejectTask(new Error(result.error)); };
    const error = (cause) => { clear(); rejectTask(cause); };
    const exited = (code) => { clear(); rejectTask(new Error(`Measurement worker exited before completing a seed (${code}).`)); };
    worker.once('message', message); worker.once('error', error); worker.once('exit', exited);
    worker.postMessage(task);
  });
}

async function runCommand(output, values) {
  const settings = CONFIG.measurement;
  const phase = values.phase ?? 'baseline';
  if (!['baseline', 'candidate', 'release'].includes(phase)) fail('Unknown phase.');
  const screening = values.screening === true;
  const workers = values.workers === undefined ? 1 : Number(values.workers);
  if (!integer(workers, 1, 4)) fail('--workers must be an integer from 1 to 4.');
  const seedSet = values['seed-set'] ?? (screening ? 'exploration' : phase === 'baseline' ? 'baseline' : 'validation');
  if (screening && (phase !== 'candidate' || seedSet !== 'exploration')) fail('--screening requires --phase candidate and exploration seeds.');
  const observedSettings = observationSettings(settings, screening);
  const seeds = settings.seeds[seedSet];
  if (!seeds || values.seed !== undefined && Number(values.seed) !== seeds.start || values.seeds !== undefined && Number(values.seeds) !== seeds.count) fail('CLI seeds must match a frozen seed set.');
  const policy = validatePolicy({ profile: values.profile ?? settings.baseline.profile, policy: values.policy ?? settings.baseline.policy,
    inputSchedule: values['input-schedule'] ?? settings.baseline.inputSchedule, management: values.management ?? settings.baseline.management,
    menuVisitSeconds: values['menu-visit-seconds'] === undefined ? settings.baseline.menuVisitSeconds : Number(values['menu-visit-seconds']) }, settings);
  const policies = values.suite ? settings.validationPolicies : [policy];
  policies.forEach((p) => validatePolicy(p, settings));
  if (phase === 'release' && !values.suite) fail('Release measurement requires --suite.');
  const protocolPath = resolve(values.protocol ?? PROTOCOL_PATH);
  const protocol = readMeasurementProtocol(protocolPath, phase);
  validateProtocol(protocol, phase !== 'baseline');
  if (phase !== 'baseline') validateOfficialProtocolSnapshot(protocol);
  if (Date.parse(protocol.frozenAt) > Date.now()) fail('Protocol must be frozen before measurement starts.');
  const experiment = selectExperiment(protocol, values, phase, seedSet);
  const fixture = values.fixture ? JSON.parse(readFileSync(resolve(values.fixture), 'utf8')) : null;
  if (fixture !== null) fail('Canonical measurement requires the registered fresh fixture (null).');
  if (existsSync(output)) {
    const report = JSON.parse(readFileSync(output, 'utf8'));
    if (phase !== 'baseline') validateOfficialProtocolSnapshot(report.protocol, report.protocolSha256);
    validateMeasurement(report, sourceDigest(), evaluationDigest());
    if (report.phase !== phase || report.seedSet !== seedSet || report.screening !== screening || !same(report.policies, policies) || report.protocolSha256 !== sha256(JSON.stringify(protocol)) ||
      !isDeepStrictEqual(report.experiment ?? null, experiment)) fail('Existing completed output belongs to another run; choose a new output path.');
    verifyBuild(report.build);
    if (experiment) validateProductionExperiment(await import(pathToFileURL(resolve(ROOT, 'dist/electron/core/index.js')).href), protocol, experiment);
    console.log(JSON.stringify({ output, resumedCompleted: true, rawComplete: true, targetsPassed: report.targets.passed }));
    if (phase !== 'baseline' && report.targets.passed === false) process.exitCode = 1;
    return;
  }
  const built = buildProduction();
  const evaluation = evaluationDigest();
  if (phase !== 'baseline') validateOfficialProtocolSnapshot(protocol);
  const core = await import(pathToFileURL(resolve(ROOT, 'dist/electron/core/index.js')).href);
  if (phase !== 'baseline' && (!core.eligibleHeroIds || !core.eligibleMonsterIds)) fail('Candidate/release requires production eligibleHeroIds(state) and eligibleMonsterIds(state), shared with actual offers/spawns.');
  if (experiment) validateProductionExperiment(core, protocol, experiment);
  const catalog = { hero: core.HERO_FORMS.map((h) => h.id), monster: [...core.SPECIES_IDS] };
  validateMilestones(protocol.milestones, catalog);
  if (phase !== 'baseline' && !protocol.milestones.some((m) => m.final)) fail('Register final unlock milestones before candidate measurement.');
  const fixtureSha256 = sha256(JSON.stringify(fixture)), protocolSha256 = sha256(JSON.stringify(protocol));
  const identity = { phase, seedSet, seeds, policies, settings, screening, checkpointsMinutes: observedSettings.checkpointsMinutes,
    sourceDigest: built.sourceDigest, evaluationDigest: evaluation, fixtureSha256, protocolSha256, buildSha256: built.build.sha256,
    ...(experiment ? { experiment } : {}) };
  const binding = sha256(JSON.stringify(identity));
  const directory = `${output}.runs`;
  mkdirSync(directory, { recursive: true });
  const manifestPath = resolve(directory, 'manifest.json');
  if (existsSync(manifestPath)) {
    const previous = JSON.parse(readFileSync(manifestPath, 'utf8'));
    if (previous.binding !== binding) fail('Resume source/evaluation/protocol/fixture/policy mismatch; choose a new output path.');
  } else writeAtomic(manifestPath, { binding, identity });
  const jobs = policies.flatMap((policy) => Array.from({ length: seeds.count }, (_, index) => {
    const seed = seeds.start + index;
    return { policy, seed, path: resolve(directory, sha256(policyKey(policy)), `${seed}.json`) };
  }));
  const runs = new Array(jobs.length), started = performance.now(), pending = [];
  let completed = 0;
  const accept = (index, run, save) => {
    const { policy, seed, path } = jobs[index];
    validateRun(run, observedSettings, protocol.milestones, catalog);
    if (run.seed !== seed || !same(run.policy, policy)) fail('Seed identity mismatch.');
    if (save) {
      if (sourceDigest() !== built.sourceDigest || evaluationDigest() !== evaluation) fail('Source/evaluation changed during measurement.');
      writeAtomic(path, { binding, sha256: sha256(JSON.stringify(run)), run });
    }
    runs[index] = run; completed++;
    if (completed % 10 === 0) console.error(`${policyKey(policy)}: ${completed}/${jobs.length} trajectories`);
  };
  for (const [index, { path }] of jobs.entries()) {
    if (existsSync(path)) {
      const saved = JSON.parse(readFileSync(path, 'utf8'));
      if (saved.binding !== binding || saved.sha256 !== sha256(JSON.stringify(saved.run))) fail('Corrupt resumed seed artifact.');
      accept(index, saved.run, false);
    } else pending.push(index);
  }
  const options = { settings: observedSettings, milestones: protocol.milestones, fixture };
  if (workers === 1) {
    for (const index of pending) {
      const job = jobs[index]; accept(index, simulate(core, job.policy, job.seed, options), true);
      await new Promise((done) => setImmediate(done));
    }
  } else {
    let cursor = 0, aborted = false;
    const results = await Promise.allSettled(Array.from({ length: Math.min(workers, pending.length) }, async () => {
      const worker = new Worker(new URL('./measure-worker.mjs', import.meta.url));
      try {
        while (!aborted && cursor < pending.length) {
          const index = pending[cursor++], job = jobs[index];
          const run = await workerSimulation(worker, { policy: job.policy, seed: job.seed, options });
          accept(index, run, true);
        }
      } catch (error) { aborted = true; throw error; }
      finally { await worker.terminate(); }
    }));
    const rejected = results.find((r) => r.status === 'rejected');
    if (rejected) throw rejected.reason;
  }
  verifyBuild(built.build);
  const report = { version: 7, kind: 'simulated-engine-measurement', phase, rawComplete: true,
    screening, checkpointsMinutes: observedSettings.checkpointsMinutes,
    sourceDigest: built.sourceDigest, evaluationDigest: evaluation, build: built.build, settings,
    protocol, protocolSha256, fixture, fixtureSha256, seedSet, seeds, policies, catalog,
    ...(experiment ? { experiment } : {}),
    runs, rawSha256: sha256(JSON.stringify(runs)), scenarios: summarize(runs), targets: evaluateTargets(runs, settings, protocol.milestones, screening),
    timing: { workers, tickMs: settings.tickMs, readinessResolutionMs: settings.tickMs, eligibilityResolutionMs: settings.observationMs,
      eligibilityEventResolutionMs: settings.tickMs, modeledMinutes: observedSettings.checkpointsMinutes.at(-1), wallElapsedSeconds: (performance.now() - started) / 1000 },
    method: { rng: 'production mulberry32', input: 'uniform=500ms; burst=20 hits/10s at 100ms; warm profiles receive 120s onboarding',
      ordering: 'tick to boundary, input, observe readiness, menu visit, observation/purchases/management; checkpoints after boundary actions',
      visits: '0 means choose immediately and manage/purchase at observation intervals; positive values require a scheduled visit',
      management: 'One action per visit: consume strongest target/weakest food; fuse first ID-ordered eligible pair; reincarnate first eligible ID, otherwise consume strongest/weakest to raise a candidate',
      choice: 'Choose first card, reroll policy attempts one paid reroll first. No PvP simulation.',
      ownership: 'chosenHero is accepted ownership, killedMonster is lifetime defeat; seen is visibility, capturedMonster is actual roster addition',
      eligibility: core.eligibleHeroIds && core.eligibleMonsterIds ? 'production exported selectors' : 'v0.6 production parseHeroProgress/requirementsMet adapter; rare conditions sampled at observation boundaries',
      eligibilityObservation: 'Sample after each engine call emitting a kill, level-up, capture or hero-ready event; before offers, rerolls, choices, purchases and roster management; and at periodic observation boundaries. Multiple events within one engine call share its returned state.',
      eligibilityLimit: 'First observed eligibility, not a continuous-time proof. A time-only condition that appears and disappears between observation boundaries without a relevant event may be missed; no universal maximum-delay guarantee.',
      damage: 'Exact emitted bigint damage including overkill; partyPower is raw production selected-party power, not effective DPS',
      resume: 'Completed seeds are fingerprinted and reused; interrupted seeds restart from initial fixture, never approximate pending attack/RNG state',
      inference: 'Modeled progression only; no claim about player fun, retention, Steam time, Electron E2E or observed human attention' },
    humanFun: 'PENDING', e2e: false };
  validateMeasurement(report, sourceDigest(), evaluationDigest());
  writeAtomic(output, report);
  console.log(JSON.stringify({ output, rawComplete: true, phase, targetsPassed: report.targets.passed, samples: runs.length, wallElapsedSeconds: report.timing.wallElapsedSeconds }));
  // Baseline is complete when evidence is valid. Its v0.7 target failure is an expected finding.
  if (phase !== 'baseline' && report.targets.passed === false) process.exitCode = 1;
}

const USAGE = 'Usage: measure.mjs run OUTPUT.json [--phase baseline|candidate|release] [--candidate ID | --control ID] [--suite] [--screening] [--workers 1..4] [--seed-set baseline|exploration|validation] [--protocol FILE] [--profile NAME] [--policy NAME] [--input-schedule uniform|burst] [--management NAME] [--menu-visit-seconds 0|120|600]\n       measure.mjs verify OUTPUT.json [--phase baseline|candidate|release]\n       measure.mjs compare BEFORE.json AFTER.json OUTPUT.json';

async function main(args) {
  const { values, positionals } = parseArgs({ args, allowPositionals: true, options: { ...Object.fromEntries([
    'phase', 'seed-set', 'seed', 'seeds', 'protocol', 'fixture', 'profile', 'policy', 'input-schedule', 'management', 'menu-visit-seconds', 'workers', 'candidate', 'control',
  ].map((key) => [key, { type: 'string' }])), suite: { type: 'boolean' }, screening: { type: 'boolean' }, help: { type: 'boolean' } } });
  if (values.help) { console.log(USAGE); return; }
  const [command, ...paths] = positionals;
  if (command === 'run' && paths.length === 1) await runCommand(resolve(paths[0]), values);
  else if (command === 'verify' && paths.length === 1) {
    if (Object.keys(values).some((key) => key !== 'phase')) fail('verify accepts only --phase baseline|candidate|release.');
    const report = JSON.parse(readFileSync(resolve(paths[0]), 'utf8'));
    if (report.phase !== 'baseline') validateOfficialProtocolSnapshot(report.protocol, report.protocolSha256);
    if (values.phase === undefined) validateMeasurement(report, sourceDigest(), evaluationDigest());
    else validateMeasurementPhase(report, values.phase, sourceDigest(), evaluationDigest());
    if (report.protocol.schemaVersion === 2) {
      verifyBuild(report.build);
      validateProductionExperiment(await import(pathToFileURL(resolve(ROOT, 'dist/electron/core/index.js')).href), report.protocol, report.experiment);
    }
    console.log(JSON.stringify({ valid: true, acceptancePhase: values.phase ?? null, phase: report.phase, rawComplete: true, targetsPassed: report.targets.passed, samples: report.runs.length }));
  } else if (command === 'compare' && paths.length === 3) {
    const report = compareMeasurements(...paths.slice(0, 2).map((p) => JSON.parse(readFileSync(resolve(p), 'utf8'))));
    writeAtomic(resolve(paths[2]), report); console.log(JSON.stringify({ output: resolve(paths[2]), pairs: report.rawDeltas.length }));
  } else fail(USAGE);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).catch((error) => { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; });
}

// Companion collection — SPEC F32 (Assumptions 5/23/24/26; GAME_DESIGN_V2
// §4/§6). Pure TypeScript, zero imports of electron/DOM/node. Every export is
// total and never mutates its input: applyCollection returns fresh objects or
// an { error }, so the caller can apply it straight onto live engine state.

import { simulateBattle } from './battle.js';
import { monsterForIndex, sizeOf, typeOf } from './monsters.js';
import { monsterMaxHp } from './formulas.js';
import { effectivePower } from './types-chart.js';
import type { MonsterType } from './types-chart.js';
import type { BattleHeroes, Blow } from './battle.js';
import { heroBuffedPower } from './hero.js';
import type { HeroAction, HeroRoll } from './hero.js';
import type { EconomyAction } from './economy.js';
import { acquiredDiscoveries, isDiscoveryAction, migrateProgress } from './progress.js';
import type { DiscoveryAction } from './progress.js';
import type { Companion } from './save.js';
import type { Rng } from './rng.js';
import type { GameState, PvpResultAction } from './types.js';

/** Reincarnation unlocks here; companion growth has no gameplay level cap. */
export const COMPANION_REINCARNATION_LEVEL = 10;

/** How many companions fight together — field volley and PvP party (F61). */
export const PARTY_SIZE = 5;

/** Roster cap (save.ts keeps its own copy for parsing). */
export const ROSTER_CAP = 30;

/** Rebirth unlocks at this monster index (Assumption 5). */
export const REBIRTH_MIN_INDEX = 40;

/** Companion attack power (Assumption 24) — bigint, unbounded. */
export const companionPower = (c: Companion): bigint => {
  const base = monsterMaxHp(c.bossIndex) / 20n;
  return (base < 1n ? 1n : base) * BigInt(c.level) * 2n ** BigInt(c.stars);
};

export type CompanionSnapshot = Pick<Companion, 'speciesId' | 'bossIndex' | 'level' | 'stars'>;

/** Confirmation crosses IPC; reject malformed or imprecise counters before use. */
export function isCompanionSnapshot(value: unknown): value is CompanionSnapshot {
  if (!value || typeof value !== 'object') return false;
  const c = value as Record<string, unknown>;
  return typeof c['speciesId'] === 'string' && c['speciesId'].length > 0 &&
    Number.isSafeInteger(c['bossIndex']) && Number(c['bossIndex']) >= 0 &&
    Number.isSafeInteger(c['level']) && Number(c['level']) >= 1 &&
    Number.isSafeInteger(c['stars']) && Number(c['stars']) >= 0;
}

/** Exact preview: at Lv10 the reset retains one fifth of the previous power. */
export function companionReincarnationPreview(c: Companion):
  { level: 1; stars: number; beforePower: bigint; afterPower: bigint } | null {
  if (!isCompanionSnapshot(c) || c.level < COMPANION_REINCARNATION_LEVEL || !Number.isSafeInteger(c.stars + 1)) return null;
  return { level: 1, stars: c.stars + 1, beforePower: companionPower(c),
    afterPower: companionPower({ ...c, level: 1, stars: c.stars + 1 }) };
}

/** Numeric part of a 'cN' id — the tie-breaker (same rule as parseSave). */
const idNum = (id: string): number => Number(id.replace(/\D/g, '') || 0);

/** Descending bigint comparator. */
const desc = (a: bigint, b: bigint): number => (a === b ? 0 : b > a ? 1 : -1);

/**
 * The PARTY_SIZE best companions against `enemyType` (F61): effective power
 * desc, ties → higher raw power → lower numeric id. Without a type the raw
 * power decides, which is what the PvP default `autoParty` wants.
 */
export function activeCompanions(
  cs: readonly Companion[],
  enemyType?: MonsterType,
  hero?: HeroRoll,
): Companion[] {
  const power = (c: Companion): bigint => heroBuffedPower(companionPower(c), typeOf(c.speciesId), hero);
  const effective = (c: Companion): bigint =>
    enemyType === undefined
      ? power(c)
      : effectivePower(power(c), typeOf(c.speciesId), enemyType);
  return [...cs]
    .sort(
      (a, b) =>
        desc(effective(a), effective(b)) ||
        desc(companionPower(a), companionPower(b)) ||
        idNum(a.id) - idNum(b.id),
    )
    .slice(0, PARTY_SIZE);
}

/** The PvP default party: the PARTY_SIZE strongest by raw power. */
export function autoParty(cs: readonly Companion[], hero?: HeroRoll): Companion[] {
  return activeCompanions(cs, undefined, hero);
}

/** `ids` resolved against `cs` in the given order; unknown/duplicate dropped. */
function resolveIds(cs: readonly Companion[], ids: readonly string[]): Companion[] {
  const party: Companion[] = [];
  for (const id of ids) {
    if (party.length >= PARTY_SIZE) break;
    const c = cs.find((x) => x.id === id);
    if (c && !party.includes(c)) party.push(c);
  }
  return party;
}

/** The manual PvP party; an empty result falls back to `autoParty` (F61). */
export function pvpParty(cs: readonly Companion[], ids: readonly string[], hero?: HeroRoll): Companion[] {
  const party = resolveIds(cs, ids);
  return party.length > 0 ? party : autoParty(cs, hero);
}

/** Draw order of a party: biggest first (back row), ties keep party order. */
export function partyOrder(party: readonly Companion[]): Companion[] {
  return [...party].sort((a, b) => sizeOf(b.speciesId) - sizeOf(a.speciesId));
}

/**
 * Events produced here (GAME_DESIGN_V2 §6). T28 folds both variants into the
 * `GameEvent` union in types.ts; every other action returns no events.
 * ponytail: declared locally until then — types.ts is owned by T26/T28/T29.
 */
export type CollectionEvent =
  | { type: 'rebirth'; souls: number }
  | { type: 'pvpResolved'; won: boolean; stolen: Companion | null; lostId: string | null };

/** Every roster/prestige operation the menu and the net layer can request. */
export type CollectionAction =
  | HeroAction
  | EconomyAction
  | DiscoveryAction
  /** Main-origin absolute counters; never accepted from MENU_ACTION. */
  | { type: 'syncPvpProgress'; wins: number; losses: number }
  | { type: 'consume'; targetId: string; foodId: string }
  | { type: 'fuse'; aId: string; bId: string }
  | { type: 'reincarnate'; id: string; expected?: CompanionSnapshot }
  | { type: 'sacrifice'; id: string }
  | { type: 'rebirth' }
  | { type: 'addCompanion'; companion: Companion }
  | { type: 'removeCompanions'; ids: string[] }
  | { type: 'setPvpParty'; ids: string[] }
  | PvpResultAction;

export type CollectionResult =
  | { state: GameState; events: CollectionEvent[] }
  | { error: string };

/** Fresh roster: `dropIds` removed, `editId` replaced by `edit(c)`, rest copied. */
function reroster(
  cs: readonly Companion[],
  dropIds: readonly string[],
  editId?: string,
  edit?: (c: Companion) => Companion,
): Companion[] {
  return cs
    .filter((c) => !dropIds.includes(c.id))
    .map((c) => (edit && c.id === editId ? edit(c) : { ...c }));
}

/** Fresh state: nothing of `state` is shared with the result. */
function next(
  state: Readonly<GameState>,
  companions: Companion[],
  patch: Partial<GameState> = {},
  events: CollectionEvent[] = [],
): CollectionResult {
  return {
    state: {
      ...state,
      items: { ...state.items },
      monster: { ...state.monster },
      companions,
      ...patch,
    },
    events,
  };
}

/** Keep server transfer IDs so the theft ledger survives the next save/upload. */
function minted(
  companions: Companion[],
  nextCompanionId: number,
  c: Companion,
): Companion | null {
  if (companions.length >= ROSTER_CAP) return null;
  // Legacy/local callers still receive a fresh local ID; the server owns s/r IDs.
  const id = /^[sr][0-9a-f]+$/.test(c.id) ? c.id : `c${nextCompanionId}`;
  if (companions.some((existing) => existing.id === id)) return null;
  const fresh: Companion = { ...c, id };
  companions.push(fresh);
  return fresh;
}

/**
 * Apply one lifecycle action (Assumption 26). Total: an unknown action type,
 * an unknown/duplicate companion id or an unmet precondition yields
 * `{ error }` and the caller keeps its state; success yields a brand-new
 * state plus the events of GAME_DESIGN_V2 §6.
 */
export function applyCollection(
  state: Readonly<GameState>,
  action: CollectionAction,
): CollectionResult {
  const cs = state.companions;
  const find = (id: string): Companion | undefined => cs.find((c) => c.id === id);

  switch (action.type) {
    case 'acknowledgeDiscoveries':
    case 'setDiscoveryGoal': {
      if (!isDiscoveryAction(action)) return { error: 'discovery: invalid action' };
      const progress = migrateProgress(state, state.monster.speciesId);
      const codex = progress.codex!;
      if (action.type === 'setDiscoveryGoal') codex.goal = action.goal ? { kind: action.goal.kind, id: action.goal.id } : null;
      else {
        const acquired = acquiredDiscoveries({ ...state, progress });
        // A displayed snapshot can acknowledge only actually acquired entries.
        codex.acknowledgedHeroes = [...new Set([...codex.acknowledgedHeroes,
          ...action.heroes.filter((id) => acquired.heroes.includes(id))])];
        codex.acknowledgedMonsters = [...new Set([...codex.acknowledgedMonsters,
          ...action.monsters.filter((id) => acquired.monsters.includes(id))])];
      }
      return next(state, reroster(cs, []), { progress });
    }
    case 'consume': {
      const target = find(action.targetId);
      const food = find(action.foodId);
      if (!target || !food || target.id === food.id) return { error: 'consume: bad ids' };
      const level = target.level + 1 + food.stars;
      if (!Number.isSafeInteger(level) || level < 1) return { error: 'consume: level overflow' };
      return next(
        state,
        reroster(cs, [food.id], target.id, (c) => ({
          ...c,
          level,
        })),
      );
    }
    case 'fuse': {
      const a = find(action.aId);
      const b = find(action.bId);
      if (!a || !b || a.id === b.id) return { error: 'fuse: bad ids' };
      if (a.speciesId !== b.speciesId || a.stars !== b.stars) {
        return { error: 'fuse: needs the same species and stars' };
      }
      if (!Number.isSafeInteger(a.stars + 1)) return { error: 'fuse: stars overflow' };
      return next(
        state,
        reroster(cs, [b.id], a.id, (c) => ({
          ...c,
          bossIndex: Math.max(a.bossIndex, b.bossIndex),
          level: 1,
          stars: c.stars + 1,
        })),
      );
    }
    case 'reincarnate': {
      const c = find(action.id);
      if (!c) return { error: 'reincarnate: unknown id' };
      if (!Number.isSafeInteger(c.level) || c.level < COMPANION_REINCARNATION_LEVEL) return { error: 'reincarnate: needs level 10' };
      if (!Number.isSafeInteger(c.stars + 1)) return { error: 'reincarnate: stars overflow' };
      if (action.expected !== undefined && (!isCompanionSnapshot(action.expected) ||
        action.expected.speciesId !== c.speciesId || action.expected.bossIndex !== c.bossIndex ||
        action.expected.level !== c.level || action.expected.stars !== c.stars)) return { error: 'reincarnate: confirmation changed' };
      return next(
        state,
        reroster(cs, [], c.id, (x) => ({ ...x, level: 1, stars: x.stars + 1 })),
      );
    }
    case 'sacrifice': {
      const c = find(action.id);
      if (!c) return { error: 'sacrifice: unknown id' };
      const souls = state.souls + 1 + c.stars;
      if (!Number.isSafeInteger(souls)) return { error: 'sacrifice: souls overflow' };
      return next(state, reroster(cs, [c.id]), { souls });
    }
    case 'rebirth': {
      if (state.monster.index < REBIRTH_MIN_INDEX) {
        return { error: `rebirth: needs monster index ${REBIRTH_MIN_INDEX}` };
      }
      const souls = state.souls + Math.floor(state.monster.index / 8);
      const first = monsterForIndex(0);
      return next(
        state,
        reroster(cs, []),
        {
          level: 1,
          xp: 0,
          monster: first,
          monsterHp: first.maxHp,
          souls,
          rebirths: state.rebirths + 1,
        },
        [{ type: 'rebirth', souls }],
      );
    }
    case 'addCompanion': {
      const companions = reroster(cs, []);
      if (!minted(companions, state.nextCompanionId, action.companion)) {
        return { error: 'addCompanion: roster is full or id already exists' };
      }
      return next(state, companions, { nextCompanionId: state.nextCompanionId + 1 });
    }
    case 'removeCompanions':
      return next(state, reroster(cs, action.ids));
    case 'setPvpParty':
      // Never an error and no event: an all-unknown list just empties it.
      return next(state, reroster(cs, []), {
        pvpParty: resolveIds(cs, action.ids).map((c) => c.id),
      });
    case 'pvpResult': {
      if (action.stolen && /^[sr][0-9a-f]+$/.test(action.stolen.id) && cs.some((c) => c.id === action.stolen!.id)) {
        return { error: 'pvpResult: transferred id already exists' };
      }
      const companions = reroster(cs, action.lostId === null ? [] : [action.lostId]);
      // A steal into a full roster is void, never an error (Assumption 23).
      const stolen = action.stolen && minted(companions, state.nextCompanionId, action.stolen);
      return next(
        state,
        companions,
        { nextCompanionId: state.nextCompanionId + (stolen ? 1 : 0) },
        [
          {
            type: 'pvpResolved',
            won: action.won,
            stolen: stolen ?? null,
            lostId: action.lostId,
          },
        ],
      );
    }
    default:
      return { error: 'unknown action' };
  }
}

/** Chance an attacking win also carries a companion home (GAME_DESIGN_V3 §5). */
export const STEAL_CHANCE = 0.15;

/**
 * Resolve one asynchronous PvP exchange (SPEC F37; GAME_DESIGN_V3 §5). The
 * verdict and the blow list come from the seedless `simulateBattle`; the rng
 * only decides the loot. Shared byte-for-byte with the server, which calls it
 * with `mulberry32(seed)` and moves `moved` between the stored rosters — so
 * exactly 2 draws happen per call, the victim draw included even when nobody
 * can be stolen, and the client can replay the same match from the seed.
 * Only the attacker ever steals: a losing attacker keeps its whole roster.
 * ponytail: `attackerRosterSize` defaults to the party size so the v2 3-arg
 * call still compiles; T60 passes the real roster length.
 */
export function resolvePvp(
  attacker: readonly Companion[],
  defender: readonly Companion[],
  rng: Rng,
  attackerRosterSize = attacker.length,
  heroes: BattleHeroes = {},
): { attackerWon: boolean; moved: Companion | null; blows: Blow[] } {
  const { attackerWon, blows } = simulateBattle(attacker, defender, heroes);
  const stealRoll = rng.next() < STEAL_CHANCE;
  const victim = defender[Math.floor(rng.next() * defender.length)] ?? null;
  return {
    attackerWon,
    moved: attackerWon && stealRoll && attackerRosterSize < ROSTER_CAP ? victim : null,
    blows,
  };
}

// Main-process IPC handlers (SPEC F17 + F22 main half; GAME_ARCHITECTURE §3.2).

import { randomUUID } from 'node:crypto';
import { app, BrowserWindow, ipcMain, shell } from 'electron';
import type { WebContents } from 'electron';
import type { CollectionAction } from '../core/collection.js';
import { isCompanionSnapshot, isDiscoveryAction, migrateProgress, parseSave } from '../core/index.js';
import type { SaveFile } from '../core/save.js';
import { isHeroRoll } from '../core/hero.js';
import { LEADERBOARD_DEFAULT, LEADERBOARD_MAX } from '../shared/api.js';
import type {
  IdentityPayload,
  LeaderboardResult,
  MatchResult,
  NetResult,
  OpponentListResult,
  PvpResult,
  ReclaimResult,
  TheftsResult,
} from '../shared/api.js';
import { IPC } from '../shared/ipc.js';
import type {
  InputModePayload,
  IpcChannel,
  LeaderboardQueryPayload,
  MoveWindowPayload,
  PvpPayload,
  PvpMatchPayload,
  ReclaimPayload,
  SetNamePayload,
} from '../shared/ipc.js';
import { SERVER_URL } from '../shared/serverUrl.js';
import { getCurrentInputMode } from './globalInput.js';
import { createNetClient, createNetSession, type NetSession } from './net.js';
import { readSaveFile, writeSaveFile } from './persistence.js';

/** Deep link to the macOS Privacy & Security → Accessibility pane. */
export const ACCESSIBILITY_SETTINGS_URL =
  'x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility';

/**
 * Stateless relay (SPEC F51): deliver `payload` to every window EXCEPT the one
 * that sent the event. With the overlay + the menu that is exact and needs no
 * window registry, so src/main/index.ts stays untouched.
 */
function sendToOthers(sender: WebContents, channel: IpcChannel, payload: unknown): void {
  for (const win of BrowserWindow.getAllWindows()) {
    if (win.webContents.id !== sender.id) {
      win.webContents.send(channel, payload);
    }
  }
}

/**
 * Broadcast main-owned updates to every window: companion reclaim and the
 * absolute official PvP counters. Menu actions cannot originate those counters.
 */
export function sendToAll(channel: IpcChannel, payload: unknown): void {
  for (const win of BrowserWindow.getAllWindows()) {
    win.webContents.send(channel, payload);
  }
}

/**
 * A `pvpResult.replay` (BattleReplay) as the menu hands it over: opponent name,
 * its party and the blow list. ponytail: the companions are only shape-checked
 * as an array — the battle scene just draws them, and a bad replay is dropped
 * (the verdict still applies), so it costs an animation, never the roster.
 */
function isReplay(v: unknown): boolean {
  const r = (v ?? {}) as Record<string, unknown>;
  const blows = r['blows'];
  return (
    typeof r['opponentName'] === 'string' &&
    Array.isArray(r['opponentParty']) &&
    (r['opponentHero'] === undefined || isHeroRoll(r['opponentHero'])) &&
    Array.isArray(blows) &&
    blows.every((b) => {
      const blow = (b ?? {}) as Record<string, unknown>;
      return (
        (blow['side'] === 'A' || blow['side'] === 'D') &&
        typeof blow['actorId'] === 'string' &&
        typeof blow['targetId'] === 'string' &&
        typeof blow['damage'] === 'string' &&
        typeof blow['ko'] === 'boolean'
      );
    })
  );
}

/**
 * Narrow an untrusted menu payload to a CollectionAction: `type` must be in
 * core's union and every id field a string (id lists, arrays of strings).
 * Anything else yields null and is dropped — the menu must not be able to
 * inject junk into the game window's state, and a bad payload never throws.
 * Nested companions use the save validator before entering the live engine.
 */
function narrowAction(payload: unknown): CollectionAction | null {
  const a = (payload ?? {}) as Record<string, unknown>;
  const str = (k: string): boolean => typeof a[k] === 'string';
  const companion = (k: string): boolean => parseSave({ companions: [a[k]] }).companions.length === 1;
  const strs = (k: string): boolean => {
    const v = a[k];
    return Array.isArray(v) && v.every((id) => typeof id === 'string');
  };
  const ok = ((): boolean => {
    switch (a['type']) {
      case 'acknowledgeDiscoveries':
      case 'setDiscoveryGoal':
        return isDiscoveryAction(payload);
      case 'consume':
        return str('targetId') && str('foodId');
      case 'fuse':
        return str('aId') && str('bId');
      case 'reincarnate':
        return str('id') && isCompanionSnapshot(a['expected']);
      case 'sacrifice':
        return str('id');
      case 'rebirth':
      case 'heroOffer':
        return true;
      case 'heroReroll':
      case 'heroDefer':
        return Number.isSafeInteger(a['offerSerial']) && Number(a['offerSerial']) >= 0;
      case 'heroChoose':
        return str('formId') && Number.isSafeInteger(a['offerSerial']) && Number(a['offerSerial']) >= 0;
      case 'heroEquip':
        return str('formId');
      case 'shopBuy':
        return (a['item'] === 'training' || a['item'] === 'lure') &&
          Number.isSafeInteger(a['shopSerial']) && Number(a['shopSerial']) >= 0;
      case 'addCompanion':
        return companion('companion');
      case 'removeCompanions':
      case 'setPvpParty':
        return strs('ids');
      case 'pvpResult':
        // The replay is optional and only animated: a malformed one is DROPPED
        // and the verdict still applies (F73).
        if (!isReplay(a['replay'])) {
          delete a['replay'];
        }
        return (
          typeof a['won'] === 'boolean' &&
          (a['stolen'] === null || companion('stolen')) &&
          (a['lostId'] === null || str('lostId'))
        );
      default:
        return false;
    }
  })();
  return ok ? (a as unknown as CollectionAction) : null;
}

export interface IpcOptions {
  /** Fired when the renderer reports its first painted frame (smoke, T13). */
  onFirstFrame?: () => void;
}

/**
 * Register all renderer→main handlers. Call once, before the window loads.
 * Returns the net session it owns, so the theft watcher (F74) shares it
 * instead of opening a second identity of its own.
 */
export function registerIpcHandlers(options: IpcOptions = {}): NetSession {
  // SPEC F49: smoke runs offline BY CODE — an empty baseUrl makes the net
  // client resolve `{ ok: false, error: 'offline' }` without ever calling
  // fetch, so `npm run smoke` needs no network and no server.
  const baseUrl = process.env.SMOKE ? '' : (process.env.DESMON_SERVER_URL ?? SERVER_URL);
  const session = createNetSession({
    client: createNetClient({ baseUrl }),
    userDataDir: app.getPath('userData'),
    online: baseUrl !== '',
    randomUUID,
  });

  const withOfficialRecord = (save: SaveFile): SaveFile => {
    const { wins, losses } = session.pvpHistory();
    if (!save.progress && wins === 0 && losses === 0) return save;
    const progress = migrateProgress(save);
    progress.pvpWins = wins;
    progress.pvpLosses = losses;
    return { ...save, progress };
  };

  // Live state from the T04 global-input state machine; before/without
  // startGlobalInput (e.g. SMOKE=1) it reports the fallback default.
  ipcMain.handle(IPC.GET_INPUT_MODE, (): InputModePayload => getCurrentInputMode());

  // Raw parsed JSON or null — validation is core's job (T08).
  ipcMain.handle(IPC.LOAD_STATE, (): unknown => {
    const raw = readSaveFile(app.getPath('userData'));
    return raw === null && session.pvpHistory().wins === 0 && session.pvpHistory().losses === 0
      ? null : withOfficialRecord(parseSave(raw));
  });

  ipcMain.handle(IPC.SAVE_STATE, (event, data: unknown): boolean => {
    // The renderer's save is untrusted input: parse it, never cast it. The
    // session uploads in the background and its result is deliberately
    // dropped — main never pushes roster changes at the game window.
    const parsed = parseSave(data);
    Object.assign(parsed, withOfficialRecord(parsed));
    if (!writeSaveFile(app.getPath('userData'), parsed)) {
      sendToAll(IPC.SAVE_FAILED, undefined);
      return false;
    }
    session.onSave(parsed);
    // …but the OTHER window (the menu) is showing a save it did not write.
    sendToOthers(event.sender, IPC.STATE_CHANGED, parsed);
    return true;
  });

  // Menu → game relay (SPEC F51). Unknown/malformed actions are ignored.
  ipcMain.handle(IPC.MENU_ACTION, (event, payload: unknown): void => {
    const action = narrowAction(payload);
    if (action !== null) {
      sendToOthers(event.sender, IPC.ACTION, action);
    }
  });

  ipcMain.handle(IPC.GET_IDENTITY, (): IdentityPayload => session.identity());

  ipcMain.handle(IPC.SET_NAME, (_event, payload: unknown): IdentityPayload => {
    const { name } = (payload as Partial<SetNamePayload> | null | undefined) ?? {};
    return session.setName(name);
  });

  ipcMain.handle(IPC.LEADERBOARD, (_event, p: unknown): Promise<NetResult<LeaderboardResult>> => {
    const { n } = (p as Partial<LeaderboardQueryPayload> | null | undefined) ?? {};
    const count =
      typeof n === 'number' && Number.isFinite(n)
        ? Math.min(Math.max(Math.trunc(n), 1), LEADERBOARD_MAX)
        : LEADERBOARD_DEFAULT;
    return session.leaderboard(count);
  });

  // v3 (T67) step 1: the opponent preview the player picks a party against.
  ipcMain.handle(IPC.PVP_OPPONENTS, (): Promise<NetResult<OpponentListResult>> => session.opponents());
  ipcMain.handle(IPC.PVP_MATCH, (_event, p: unknown): Promise<NetResult<MatchResult>> => {
    const { opponentId } = (p as Partial<PvpMatchPayload> | null | undefined) ?? {};
    return opponentId === undefined || (typeof opponentId === 'string' && /^[A-Za-z0-9-]{1,64}$/.test(opponentId))
      ? session.match(opponentId)
      : Promise.resolve({ ok: false, error: 'network' });
  });

  // v3 (T67) step 2: the battle needs the match from step 1 and my chosen
  // party. The payload is untrusted; a malformed one is refused, never sent.
  ipcMain.handle(IPC.PVP, (_event, p: unknown): Promise<NetResult<PvpResult>> => {
    const { matchId, party } = (p as Partial<PvpPayload> | null | undefined) ?? {};
    return typeof matchId === 'string' && Array.isArray(party) && party.every((id) => typeof id === 'string')
      ? session.pvp(matchId, party).then((result) => {
        if (result.ok) {
          const { wins, losses } = session.pvpHistory();
          sendToAll(IPC.ACTION, { type: 'syncPvpProgress', wins, losses });
        }
        return result;
      })
      : Promise.resolve({ ok: false, error: 'network' });
  });

  ipcMain.handle(IPC.THEFTS, (): Promise<NetResult<TheftsResult>> => session.thefts());

  ipcMain.handle(IPC.RECLAIM, (_event, p: unknown): Promise<NetResult<ReclaimResult>> => {
    const { theftId } = (p as Partial<ReclaimPayload> | null | undefined) ?? {};
    return typeof theftId === 'string'
      ? session.reclaim(theftId)
      : Promise.resolve({ ok: false, error: 'network' });
  });

  ipcMain.handle(IPC.OPEN_ACCESSIBILITY_SETTINGS, async (): Promise<void> => {
    await shell.openExternal(ACCESSIBILITY_SETTINGS_URL);
  });

  // The menu's single boot path: answer the SENDER with the save on disk.
  ipcMain.on(IPC.MENU_READY, (event) => {
    event.sender.send(IPC.STATE_CHANGED, withOfficialRecord(parseSave(readSaveFile(app.getPath('userData')))));
  });

  ipcMain.on(IPC.FIRST_FRAME, () => {
    options.onFirstFrame?.();
  });

  // Whole-window drag (SPEC Assumption 10): the renderer streams cursor
  // deltas while a drag is in flight; moving the window that SENT the event
  // keeps this handler stateless. Deltas are validated — a compromised
  // renderer must not be able to throw the window to NaN-land.
  ipcMain.on(IPC.MOVE_WINDOW, (event, payload: unknown) => {
    const win = BrowserWindow.fromWebContents(event.sender);
    if (win === null) {
      return;
    }
    const delta = payload as Partial<MoveWindowPayload> | null | undefined;
    const dx = typeof delta?.dx === 'number' && Number.isFinite(delta.dx) ? Math.round(delta.dx) : 0;
    const dy = typeof delta?.dy === 'number' && Number.isFinite(delta.dy) ? Math.round(delta.dy) : 0;
    if (dx === 0 && dy === 0) {
      return;
    }
    const [x = 0, y = 0] = win.getPosition();
    win.setPosition(x + dx, y + dy);
  });

  return session;
}

// v0.5 lifetime discovery/history. No clocks, randomness, or platform imports.
import { RARE_HERO_FORMS } from './discovery.js';
import type { DiscoveryContext } from './discovery.js';
import type { HeroProgress } from './hero.js';
import { isSpeciesId, typeOf } from './monsters.js';
import type { MonsterType } from './types-chart.js';

export interface ReincarnationRecord {
  number: number;
  formId: string;
  level: number;
  playTimeMs: number;
  buffPercent: number;
  stacks: number;
}
export interface DiscoveryGoal { kind: 'hero' | 'monster'; id: string }
export interface CodexProgress {
  acknowledgedHeroes: string[];
  acknowledgedMonsters: string[];
  goal: DiscoveryGoal | null;
}
export type DiscoveryAction =
  | { type: 'acknowledgeDiscoveries'; heroes: string[]; monsters: string[] }
  | { type: 'setDiscoveryGoal'; goal: DiscoveryGoal | null };
export interface Progress {
  playTimeMs: number;
  speciesKills: Record<string, number>;
  seenMonsters: string[];
  seenHeroes: string[];
  heroCounts: Record<string, number>;
  reincarnationHistory: ReincarnationRecord[];
  pvpWins: number;
  pvpLosses: number;
  goldSpent: number;
  rareMisses: number;
  trainingLevel: number;
  lureRemaining: number;
  shopSerial: number;
  legacyHistory: boolean;
  /** Absent only in old saves, until their existing discoveries are baselined. */
  codex?: CodexProgress;
}
export interface ProgressSource {
  killCount: number;
  hero?: HeroProgress;
  progress?: Progress;
  monsterSpeciesId?: string;
  companions?: readonly { speciesId: string }[];
}

export const HISTORY_LIMIT = 100;
const MAX = Number.MAX_SAFE_INTEGER;
const MAX_REINCARNATIONS = 1_000_000;
// The standard IDs are frozen; rare identity comes from the content catalog.
const isHeroId = (id: string): boolean => /^h(?:0[1-9]|[1-4][0-9]|50)$/.test(id) ||
  RARE_HERO_FORMS.some((form) => form.id === id);
const record = (value: unknown): Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : {};
const integer = (value: unknown, max = MAX): number =>
  typeof value === 'number' && Number.isSafeInteger(value) ? Math.max(0, Math.min(max, value)) : 0;
const milliseconds = (value: unknown): number =>
  typeof value === 'number' && Number.isFinite(value) ? Math.max(0, Math.min(MAX, value)) : 0;

export function newProgress(legacyHistory = false): Progress {
  return { playTimeMs: 0, speciesKills: {}, seenMonsters: [], seenHeroes: [], heroCounts: {},
    reincarnationHistory: [], pvpWins: 0, pvpLosses: 0, goldSpent: 0, rareMisses: 0,
    trainingLevel: 0, lureRemaining: 0, shopSerial: 0, legacyHistory,
    codex: { acknowledgedHeroes: [], acknowledgedMonsters: [], goal: null } };
}
export function copyProgress(progress: Progress): Progress {
  return { ...progress, speciesKills: { ...progress.speciesKills }, heroCounts: { ...progress.heroCounts },
    seenMonsters: [...progress.seenMonsters], seenHeroes: [...progress.seenHeroes],
    reincarnationHistory: progress.reincarnationHistory.map((entry) => ({ ...entry })),
    ...(progress.codex ? { codex: { acknowledgedHeroes: [...progress.codex.acknowledgedHeroes],
      acknowledgedMonsters: [...progress.codex.acknowledgedMonsters],
      goal: progress.codex.goal ? { ...progress.codex.goal } : null } } : {}) };
}
function counts(value: unknown, valid: (id: string) => boolean, max = MAX): Record<string, number> {
  return Object.fromEntries(Object.entries(record(value)).flatMap(([id, value]) => {
    const n = integer(value, max);
    return valid(id) && n > 0 ? [[id, n]] : [];
  }));
}
function ids(value: unknown, valid: (id: string) => boolean): string[] {
  return Array.isArray(value) ? [...new Set(value.filter((id): id is string => typeof id === 'string' && valid(id)))] : [];
}

/** Codex disclosure is acquisition, independent of offer/spawn eligibility history. */
export function acquiredDiscoveries(source: ProgressSource): { heroes: string[]; monsters: string[] } {
  const progress = source.progress;
  const positive = (entries: Record<string, number> | undefined): string[] =>
    Object.entries(entries ?? {}).filter(([, count]) => Number.isSafeInteger(count) && count > 0).map(([id]) => id);
  return {
    heroes: ids([...positive(progress?.heroCounts),
      ...(progress?.reincarnationHistory ?? []).map((entry) => entry.formId),
      ...(source.hero?.collection ?? []).map((entry) => entry.formId)], isHeroId),
    monsters: ids(positive(progress?.speciesKills), isSpeciesId),
  };
}

export function isDiscoveryGoal(value: unknown): value is DiscoveryGoal {
  const goal = record(value);
  return typeof goal.id === 'string' && (goal.kind === 'hero' ? isHeroId(goal.id)
    : goal.kind === 'monster' && isSpeciesId(goal.id));
}

/** Shared validation for IPC and direct engine callers; no unknown IDs enter UI state. */
export function isDiscoveryAction(value: unknown): value is DiscoveryAction {
  const action = record(value);
  if (action.type === 'setDiscoveryGoal') return action.goal === null || isDiscoveryGoal(action.goal);
  const validIds = (value: unknown, valid: (id: string) => boolean): boolean =>
    Array.isArray(value) && value.every((id: unknown) => typeof id === 'string' && valid(id));
  return action.type === 'acknowledgeDiscoveries' && validIds(action.heroes, isHeroId) &&
    validIds(action.monsters, isSpeciesId);
}

/** Preserve absent v5 fields when parsing a legacy save; migrate only on engine boot. */
export function parseProgress(value: unknown): Progress | undefined {
  if (value === undefined) return undefined;
  const p = record(value);
  const seenHeroes = ids(p.seenHeroes, isHeroId);
  const seenMonsters = ids(p.seenMonsters, isSpeciesId);
  const codex = record(p.codex);
  const seenNumbers = new Set<number>();
  const history: ReincarnationRecord[] = [];
  if (Array.isArray(p.reincarnationHistory)) for (const raw of p.reincarnationHistory) {
    const entry = record(raw);
    const n = integer(entry.number, MAX_REINCARNATIONS);
    if (n === 0 || n !== entry.number || seenNumbers.has(n) || typeof entry.formId !== 'string' || !isHeroId(entry.formId) ||
      !Number.isSafeInteger(entry.level) || Number(entry.level) < 1 ||
      !Number.isSafeInteger(entry.buffPercent) || Number(entry.buffPercent) < 10 || Number(entry.buffPercent) > 25 ||
      !Number.isSafeInteger(entry.stacks) || Number(entry.stacks) < 0 || Number(entry.stacks) > MAX_REINCARNATIONS ||
      typeof entry.playTimeMs !== 'number' || !Number.isFinite(entry.playTimeMs) || entry.playTimeMs < 0 || entry.playTimeMs > MAX) continue;
    seenNumbers.add(n);
    history.push({ number: n, formId: entry.formId, level: Number(entry.level), playTimeMs: entry.playTimeMs,
      buffPercent: Number(entry.buffPercent), stacks: Number(entry.stacks) });
  }
  return { playTimeMs: milliseconds(p.playTimeMs), speciesKills: counts(p.speciesKills, isSpeciesId),
    seenMonsters, seenHeroes,
    heroCounts: counts(p.heroCounts, isHeroId, MAX_REINCARNATIONS),
    reincarnationHistory: history.sort((a, b) => a.number - b.number).slice(-HISTORY_LIMIT),
    pvpWins: integer(p.pvpWins), pvpLosses: integer(p.pvpLosses), goldSpent: integer(p.goldSpent),
    rareMisses: integer(p.rareMisses, 11), trainingLevel: integer(p.trainingLevel, 10),
    lureRemaining: integer(p.lureRemaining, 20), shopSerial: integer(p.shopSerial, MAX - 1),
    legacyHistory: p.legacyHistory === true,
    ...(Object.hasOwn(p, 'codex') ? { codex: {
      // Acquisition needs the permanent collection too; normalize with that context on boot/UI.
      acknowledgedHeroes: ids(codex.acknowledgedHeroes, isHeroId),
      acknowledgedMonsters: ids(codex.acknowledgedMonsters, isSpeciesId),
      goal: isDiscoveryGoal(codex.goal) ? { kind: codex.goal.kind, id: codex.goal.id } : null,
    } } : {}) };
}

/** Keep spawn/offer history; normalize public ACK without inventing past monster kills. */
export function migrateProgress(source: ProgressSource, currentMonsterSpecies?: string): Progress {
  const progress = source.progress ? copyProgress(source.progress)
    : newProgress(source.killCount > 0 || (source.hero?.reincarnations ?? 0) > 0);
  if (!source.progress) {
    for (const owned of source.hero?.collection ?? []) {
      if (!isHeroId(owned.formId)) continue;
      progress.heroCounts[owned.formId] = 1;
    }
    for (const c of source.companions ?? []) if (isSpeciesId(c.speciesId) && !progress.seenMonsters.includes(c.speciesId)) {
      progress.seenMonsters.push(c.speciesId);
    }
  }
  for (const hero of [...(source.hero?.collection ?? []), ...(source.hero?.choices ?? [])]) {
    if (isHeroId(hero.formId) && !progress.seenHeroes.includes(hero.formId)) progress.seenHeroes.push(hero.formId);
  }
  const monster = currentMonsterSpecies ?? source.monsterSpeciesId;
  if (monster && isSpeciesId(monster) && !progress.seenMonsters.includes(monster)) progress.seenMonsters.push(monster);
  const acquired = acquiredDiscoveries({ ...source, progress });
  progress.codex = source.progress?.codex ? {
    acknowledgedHeroes: progress.codex!.acknowledgedHeroes.filter((id) => acquired.heroes.includes(id)),
    acknowledgedMonsters: progress.codex!.acknowledgedMonsters.filter((id) => acquired.monsters.includes(id)),
    goal: progress.codex!.goal,
  } : { acknowledgedHeroes: acquired.heroes, acknowledgedMonsters: acquired.monsters, goal: null };
  return progress;
}

/** Shared inputs for the same condition evaluator in the engine and codex. */
export function discoveryContext(source: ProgressSource, equippedType?: MonsterType): DiscoveryContext {
  const progress = source.progress ?? migrateProgress(source);
  const elementKills: Record<MonsterType, number> = { fire: 0, water: 0, wind: 0, earth: 0, dark: 0 };
  for (const [id, count] of Object.entries(progress.speciesKills)) if (isSpeciesId(id)) {
    const type = typeOf(id);
    elementKills[type] = Math.min(MAX, elementKills[type] + count);
  }
  const heroFamilyHistory = Array<number>(10).fill(0);
  for (const [id, count] of Object.entries(progress.heroCounts)) {
    const n = Number(id.slice(1));
    if (n >= 1 && n <= 50) {
      const family = (n - 1) % 10;
      heroFamilyHistory[family] = Math.min(MAX, heroFamilyHistory[family]! + count);
    }
  }
  return { killCount: source.killCount, playTimeMs: progress.playTimeMs, speciesKills: progress.speciesKills,
    elementKills, heroCounts: progress.heroCounts, heroFamilyHistory, reincarnations: source.hero?.reincarnations ?? 0,
    uniqueHeroes: Object.keys(progress.heroCounts).length, equippedType, seenMonsters: progress.seenMonsters, seenHeroes: progress.seenHeroes,
    pvpWins: progress.pvpWins, goldSpent: progress.goldSpent };
}

export function recordReincarnation(progress: Progress, hero: HeroProgress, level: number): void {
  const chosen = hero.equipped;
  progress.heroCounts[chosen.formId] = Math.min(MAX_REINCARNATIONS, (progress.heroCounts[chosen.formId] ?? 0) + 1);
  progress.reincarnationHistory.push({ number: hero.reincarnations, formId: chosen.formId, level,
    playTimeMs: progress.playTimeMs, buffPercent: chosen.buffPercent, stacks: chosen.stacks ?? 0 });
  progress.reincarnationHistory = progress.reincarnationHistory.slice(-HISTORY_LIMIT);
}

import { format } from '../core/bignum.js';
import { HERO_FORMS, heroForm, heroReadiness, heroRequiredLevel } from '../core/hero.js';
import { acquiredDiscoveries, discoveryContext, migrateProgress } from '../core/progress.js';
import {
  conditionStatus, fieldPhase, FIELD_PHASE_MS, FIELD_PHASE_NAMES, rareHero, rareMonster,
} from '../core/discovery.js';
import type { DiscoveryContext, Requirement } from '../core/discovery.js';
import {
  SPECIES_IDS, attackDelayOf, displayNameOf, monsterForIndex, typeOf,
} from '../core/monsters.js';
import type { SpeciesId } from '../core/monsters.js';
import type { DiscoveryGoal } from '../core/progress.js';
import type { CollectionAction } from '../core/collection.js';
import type { SaveFile } from '../core/save.js';
import { drawSprite, monsterSprites } from '../renderer/sprites/index.js';
import type { MenuDocument, MenuElement } from './index.js';
import { ELEMENT_NAMES, heroBuffText, heroCanvas, SILHOUETTE_COLOR } from './hero.js';

export function monsterCanvas(doc: MenuDocument, speciesId: SpeciesId, silhouette: boolean): MenuElement {
  const canvas = doc.createElement('canvas');
  canvas.className = 'monster-art';
  canvas.width = 96; canvas.height = 96;
  canvas.setAttribute?.('role', 'img');
  canvas.setAttribute?.('aria-label', silhouette ? '미발견 몬스터 실루엣' : displayNameOf(speciesId));
  const ctx = canvas.getContext?.('2d');
  const sprite = monsterSprites[speciesId].idle;
  const scale = Math.min(3, Math.floor(96 / Math.max(sprite.w, sprite.h)));
  if (ctx) drawSprite(ctx, sprite, 0, Math.floor((96 - sprite.w * scale) / 2), 96 - sprite.h * scale,
    { scale, ...(silhouette ? { tint: SILHOUETTE_COLOR } : {}) });
  return canvas;
}

type AcquiredDiscoveries = ReturnType<typeof acquiredDiscoveries>;

/** Keep condition progress public, but disclose referenced names only after acquisition. */
export function conditionText(requirement: Requirement, context: DiscoveryContext, acquired: AcquiredDiscoveries): string {
  const status = conditionStatus(requirement, context);
  let label = status.label;
  if (requirement.kind === 'speciesKills') label = label.replace(requirement.id, acquired.monsters.includes(requirement.id)
    ? displayNameOf(requirement.id) : `미발견 몬스터 #${String(SPECIES_IDS.indexOf(requirement.id as SpeciesId) + 1).padStart(3, '0')}`);
  if (requirement.kind === 'heroHistory') label = label.replace(requirement.id, acquired.heroes.includes(requirement.id)
    ? heroForm(requirement.id)?.name ?? requirement.id : `미발견 영웅 #${String(HERO_FORMS.findIndex(form => form.id === requirement.id) + 1).padStart(3, '0')}`);
  let progress = `${status.current}/${status.target}`;
  if (requirement.kind === 'playTimeMs') progress = `${Math.floor(status.current / 60_000)}/${status.target / 60_000}분`;
  if (requirement.kind === 'phase') progress = `현재 ${FIELD_PHASE_NAMES[fieldPhase(context.playTimeMs)]}`;
  if (requirement.kind === 'equippedType') progress = context.equippedType ? `현재 ${ELEMENT_NAMES[context.equippedType]}` : '현재 수습 영웅';
  return `${status.met ? '✓' : '○'} ${label}${requirement.kind === 'pvpWins' ? '' : ` · ${progress}`}`;
}

/** Create each gallery once on demand; update text in place and reveal each canvas once. */
export function mountCodex(doc: MenuDocument, root: MenuElement, send: (a: CollectionAction) => void): (save: SaveFile) => void {
  const text = (tag: string, className: string, value = ''): MenuElement => {
    const el = doc.createElement(tag); el.className = className; el.textContent = value; return el;
  };
  const heading = text('h2', 'codex-count');
  const phase = text('p', 'field-phase');
  const discoveries = text('section', 'discovery-summary');
  const unreadCount = text('p', 'discovery-count');
  const previews = text('div', 'discovery-previews');
  const acknowledge = text('button', 'btn discovery-ack', '표시한 발견 확인');
  const goalPanel = text('section', 'discovery-goal');
  const goalName = text('p', 'goal-name');
  const goalStatus = text('p', 'goal-status');
  const goalConditions = text('div', 'goal-conditions');
  const clearGoal = text('button', 'btn goal-clear', '목표 해제');
  discoveries.append(text('h3', '', '지난 확인 이후 발견'), unreadCount, previews, acknowledge,
    text('p', 'muted', '표시한 카드만 확인합니다. 나머지 발견은 확인 후 이어서 표시됩니다. 아래 전체 도감에서 모든 발견을 볼 수 있습니다.'));
  goalPanel.append(text('h3', '', '선택한 목표'), goalName, goalStatus, goalConditions, clearGoal);
  let displayed = { heroes: [] as string[], monsters: [] as string[] };
  let previewKey = '';
  acknowledge.addEventListener('click', () => {
    if (!acknowledge.disabled) send({ type: 'acknowledgeDiscoveries', heroes: [...displayed.heroes], monsters: [...displayed.monsters] });
  });
  clearGoal.addEventListener('click', () => { if (!clearGoal.disabled) send({ type: 'setDiscoveryGoal', goal: null }); });
  const tabs = text('div', 'codex-tabs');
  const heroes = text('button', 'btn codex-heroes', '영웅 도감');
  const monsters = text('button', 'btn codex-monsters', '몬스터 도감');
  tabs.append(heroes, monsters);
  const heroGrid = text('div', 'codex-grid hero-gallery');
  const monsterGrid = text('div', 'codex-grid monster-gallery');
  root.replaceChildren(heading, discoveries, goalPanel, phase, tabs,
    text('p', 'muted', '카드를 펼치면 발견 조건과 진행도를 확인할 수 있습니다. 영웅은 환생에서 선택하고, 몬스터는 처치하면 도감에 공개됩니다.'),
    heroGrid, monsterGrid);
  let active: 'hero' | 'monster' = 'hero';
  let save: SaveFile | undefined;
  type Card = { update: (state: SaveFile, context: DiscoveryContext, acquired: AcquiredDiscoveries) => void };
  let heroCards: Card[] | undefined;
  let monsterCards: Card[] | undefined;

  const makeCard = (host: MenuElement, number: number, rarity: string, element: string) => {
    const card = text('details', 'codex-card');
    const summary = text('summary', 'codex-summary');
    const art = text('span', 'codex-art');
    const name = text('span', 'name');
    const description = text('p', 'codex-description');
    const stats = text('p', 'codex-stats');
    const eligibility = text('p', 'codex-eligibility');
    const conditions = text('div', 'codex-conditions');
    summary.append(art, text('span', 'codex-number', `#${String(number).padStart(3, '0')}`),
      name, text('span', 'stars', `${rarity} · ${element}`));
    card.append(summary, description, stats, eligibility, conditions);
    host.append(card);
    return { card, art, name, description, stats, eligibility, conditions };
  };
  const bindConditions = (host: MenuElement, requirements: readonly Requirement[], fallback: string) => {
    const lines = requirements.map(() => text('p', 'condition'));
    host.append(text('p', 'muted', requirements.length > 1 ? '발견 조건 · 아래 항목 모두 충족' : '발견 조건'),
      ...(lines.length ? lines : [text('p', 'condition', fallback)]));
    return (context: DiscoveryContext, acquired: AcquiredDiscoveries): boolean => {
      requirements.forEach((r, i) => { lines[i]!.textContent = conditionText(r, context, acquired); });
      return requirements.every((r) => conditionStatus(r, context).met);
    };
  };
  const bindGoal = (host: MenuElement, goal: DiscoveryGoal) => {
    host.setAttribute?.('data-discovery-kind', goal.kind);
    host.setAttribute?.('data-discovery-id', goal.id);
    const button = text('button', 'btn codex-goal', '무료 목표 선택');
    host.append(button);
    button.addEventListener('click', () => {
      const current = save?.progress?.codex?.goal;
      send({ type: 'setDiscoveryGoal', goal: current?.kind === goal.kind && current.id === goal.id ? null : goal });
    });
    return (state: SaveFile) => {
      const current = state.progress?.codex?.goal;
      const selected = current?.kind === goal.kind && current.id === goal.id;
      button.textContent = selected ? '선택한 목표 · 해제' : '무료 목표 선택';
      button.setAttribute?.('aria-pressed', String(selected));
    };
  };
  let goalKey = '';
  let updateGoalConditions: ((context: DiscoveryContext, acquired: AcquiredDiscoveries) => boolean) | undefined;
  const updateSummary = (state: SaveFile, context: DiscoveryContext, acquired: AcquiredDiscoveries): void => {
    const progress = state.progress!;
    const codex = progress.codex;
    const heroes = acquired.heroes.filter(id => !codex?.acknowledgedHeroes.includes(id));
    const monsters = acquired.monsters.filter(id => !codex?.acknowledgedMonsters.includes(id));
    displayed = { heroes: heroes.slice(0, 3), monsters: monsters.slice(0, 3) };
    unreadCount.textContent = `영웅 ${heroes.length} · 몬스터 ${monsters.length}${heroes.length + monsters.length === 0 ? ' · 모두 확인했습니다.' : ''}`;
    acknowledge.disabled = heroes.length + monsters.length === 0;
    const key = JSON.stringify(displayed);
    if (key !== previewKey) {
      previewKey = key;
      previews.replaceChildren(...displayed.heroes.map(id => {
        const card = text('div', 'discovery-preview');
        card.append(heroCanvas(doc, id, 64), text('span', 'discovery-name', heroForm(id)?.name ?? '영웅')); return card;
      }), ...displayed.monsters.map(id => {
        const card = text('div', 'discovery-preview');
        card.append(monsterCanvas(doc, id as SpeciesId, false), text('span', 'discovery-name', displayNameOf(id as SpeciesId))); return card;
      }));
    }
    const goal = codex?.goal;
    const nextKey = JSON.stringify(goal ?? null);
    if (nextKey !== goalKey) {
      goalKey = nextKey;
      goalConditions.replaceChildren();
      const form = goal?.kind === 'hero' ? heroForm(goal.id) : undefined;
      const requirements: readonly Requirement[] = goal?.kind === 'hero'
        ? rareHero(goal.id)?.requirements ?? (form && form.rank > 1 ? [{ kind: 'reincarnations', count: form.rank - 1 }] : [])
        : goal ? rareMonster(goal.id as SpeciesId)?.requirements ?? [] : [];
      updateGoalConditions = goal ? bindConditions(goalConditions, requirements,
        goal.kind === 'hero' ? '첫 환생부터 등장 가능' : '조건 없이 필드에서 무작위 등장') : undefined;
    }
    clearGoal.disabled = !goal;
    if (!goal) { goalName.textContent = '목표 없음 · 아래 카드에서 하나를 무료로 선택하세요.'; goalStatus.textContent = ''; return; }
    const seen = goal.kind === 'hero' ? acquired.heroes.includes(goal.id) : acquired.monsters.includes(goal.id);
    const number = goal.kind === 'hero' ? HERO_FORMS.findIndex(f => f.id === goal.id) + 1 : SPECIES_IDS.indexOf(goal.id as SpeciesId) + 1;
    goalName.textContent = `${goal.kind === 'hero' ? '영웅' : '몬스터'} #${String(number).padStart(3, '0')} · ${seen ? goal.kind === 'hero' ? heroForm(goal.id)?.name ?? '영웅' : displayNameOf(goal.id as SpeciesId) : '미발견'}`;
    const eligible = updateGoalConditions?.(context, acquired) ?? false;
    const owned = goal.kind === 'hero' && state.hero?.collection.some(r => r.formId === goal.id);
    goalStatus.textContent = seen ? `발견 완료${goal.kind === 'hero' ? owned ? ' · 보유' : ' · 미보유' : ''} · 목표는 직접 변경하거나 해제할 수 있습니다.`
      : goal.kind === 'hero' && state.hero && heroReadiness(state.level, state.hero).status === 'capped' ? '환생 상한 도달 · 새 후보를 열 수 없습니다. 목표는 유지됩니다.'
      : eligible ? goal.kind === 'hero' ? `조건 충족 · 아직 미발견. Lv.${heroRequiredLevel(state.hero?.reincarnations ?? 0)} 이후 환생 후보에서 선택하면 공개됩니다.` : '조건 충족 · 아직 미발견. 다음 필드 생성 때 추첨하며, 처치하면 공개됩니다.' : '현재 조건 미충족 · 목표는 유지됩니다.';
  };
  const makeHeroes = (): Card[] => HERO_FORMS.map((form, i) => {
    const nodes = makeCard(heroGrid, i + 1, form.rarity === 'rare' ? '레어' : '일반', `${ELEMENT_NAMES[form.type]} · ${'★'.repeat(form.rank)}`);
    const requirements: readonly Requirement[] = rareHero(form.id)?.requirements ?? (form.rank > 1 ? [{ kind: 'reincarnations', count: form.rank - 1 }] : []);
    const updateGoal = bindGoal(nodes.card, { kind: 'hero', id: form.id });
    const updateConditions = bindConditions(nodes.conditions, requirements, '첫 환생부터 등장 가능');
    const button = text('button', 'btn codex-equip');
    nodes.card.append(button);
    button.addEventListener('click', () => {
      if (!button.disabled) send({ type: 'heroEquip', formId: form.id });
    });
    let revealed: boolean | undefined;
    return { update(state, context, acquired) {
      updateGoal(state);
      const seen = acquired.heroes.includes(form.id);
      const owned = state.hero?.collection.find((r) => r.formId === form.id);
      if (revealed !== seen) {
        revealed = seen;
        nodes.art.replaceChildren(heroCanvas(doc, form.id, 96, !seen));
      }
      nodes.card.className = `codex-card ${seen ? 'discovered' : 'locked'}`;
      nodes.name.textContent = seen ? form.name : '미발견';
      nodes.description.textContent = seen ? form.description : '환생 후보에서 이 영웅을 선택하면 설명과 능력치가 공개됩니다.';
      nodes.stats.textContent = seen ? owned ? `${heroBuffText(owned)} · 중첩 ${owned.stacks ?? 0} · 이 영웅으로 ${state.progress?.heroCounts[form.id] ?? 0}회 환생`
        : `${form.buff === 'element' ? `${ELEMENT_NAMES[form.type]} 동료 +20–50%` : '모든 동료 +10–25%'} · 수락 시 수치 확정, 반복 환생 시 강화` : '능력치 미발견';
      const eligible = updateConditions(context, acquired);
      nodes.eligibility.textContent = seen ? owned ? '발견 · 보유' : '발견 · 미보유'
        : state.hero && heroReadiness(state.level, state.hero).status === 'capped' ? '환생 상한 도달 · 새 후보를 열 수 없습니다.'
        : eligible ? `조건 달성 · Lv.${heroRequiredLevel(state.hero?.reincarnations ?? 0)} 이후 새 환생 후보에서 만나 보세요${state.hero?.choices.length ? ' · 현재 열린 후보는 그대로 유지됩니다.' : ''}`
          : '조건을 달성하면 환생 후보에 등장할 수 있습니다.';
      button.disabled = !owned || state.hero?.equipped.formId === form.id;
      button.textContent = !owned ? '환생으로 획득하면 장착 가능' : state.hero?.equipped.formId === form.id ? '장착 중' : '무료 장착';
    } };
  });
  const makeMonsters = (): Card[] => SPECIES_IDS.map((speciesId, i) => {
    const rare = rareMonster(speciesId);
    const nodes = makeCard(monsterGrid, i + 1, rare ? '레어' : '일반', ELEMENT_NAMES[typeOf(speciesId)]);
    const updateGoal = bindGoal(nodes.card, { kind: 'monster', id: speciesId });
    const updateConditions = bindConditions(nodes.conditions, rare?.requirements ?? [], '조건 없이 필드에서 무작위 등장');
    let revealed: boolean | undefined;
    return { update(state, context, acquired) {
      updateGoal(state);
      const seen = acquired.monsters.includes(speciesId);
      if (revealed !== seen) {
        revealed = seen;
        nodes.art.replaceChildren(monsterCanvas(doc, speciesId, !seen));
      }
      nodes.card.className = `codex-card ${seen ? 'discovered' : 'locked'}`;
      nodes.name.textContent = seen ? displayNameOf(speciesId) : '미발견';
      nodes.description.textContent = seen ? rare?.description ?? `${ELEMENT_NAMES[typeOf(speciesId)]} 속성의 ${displayNameOf(speciesId)}. 보스로 만나 쓰러뜨리면 동료로 합류할 수 있습니다.`
        : '이 몬스터를 처치하면 설명과 능력치가 공개됩니다.';
      const monster = monsterForIndex(state.monsterIndex, speciesId);
      nodes.stats.textContent = seen ? `현재 깊이 ${state.monsterIndex + 1} 기준 HP ${format(monster.maxHp)}${monster.boss ? ' (보스)' : ''} · 동료 공격 대기 ${attackDelayOf(speciesId) / 1000}초 · 누적 ${state.progress?.speciesKills[speciesId] ?? 0}회 처치`
        : '능력치 미발견';
      const eligible = updateConditions(context, acquired);
      nodes.eligibility.textContent = eligible ? '현재 등장 가능 · 다음 필드 생성 때 추첨' : seen ? '발견 완료 · 현재 출현 조건 미충족' : '조건을 달성하면 필드에 등장할 수 있습니다.';
    } };
  });

  const render = (): void => {
    if (!save || root.hidden) return;
    const state = { ...save, progress: migrateProgress(save, save.monsterSpeciesId ?? monsterForIndex(save.monsterIndex).speciesId) };
    const context = discoveryContext(state, heroForm(save.hero?.equipped.formId ?? '')?.type);
    const acquired = acquiredDiscoveries(state);
    updateSummary(state, context, acquired);
    heroGrid.hidden = active !== 'hero';
    monsterGrid.hidden = active !== 'monster';
    heroes.className = `btn codex-heroes${active === 'hero' ? ' selected' : ''}`;
    monsters.className = `btn codex-monsters${active === 'monster' ? ' selected' : ''}`;
    heroes.setAttribute?.('aria-pressed', String(active === 'hero'));
    monsters.setAttribute?.('aria-pressed', String(active === 'monster'));
    const count = active === 'hero' ? acquired.heroes.length : acquired.monsters.length;
    heading.textContent = `${active === 'hero' ? '영웅' : '몬스터'} 도감 · 발견 ${count}/${active === 'hero' ? HERO_FORMS.length : SPECIES_IDS.length}`;
    const ms = state.progress.playTimeMs;
    const seconds = Math.ceil((FIELD_PHASE_MS - ms % FIELD_PHASE_MS) / 1000);
    phase.textContent = `필드 시간 · ${FIELD_PHASE_NAMES[fieldPhase(ms)]} · 다음 전환까지 플레이 ${Math.floor(seconds / 60)}분 ${seconds % 60}초 (20분 주기)`;
    if (active === 'hero') { heroCards ??= makeHeroes(); heroCards.forEach((card) => card.update(state, context, acquired)); }
    else { monsterCards ??= makeMonsters(); monsterCards.forEach((card) => card.update(state, context, acquired)); }
  };
  heroes.addEventListener('click', () => { active = 'hero'; render(); });
  monsters.addEventListener('click', () => { active = 'monster'; render(); });
  return (next) => { save = next; render(); };
}

// Menu DOM binder — SPEC F54/F55/F75 (Assumption 29; GAME_DESIGN_V2 §9,
// GAME_DESIGN_V3 §7). A thin binder over src/menu/view.ts: it owns no game
// state, it renders the save main sends and forwards every button press as a
// CollectionAction.
//
// DOM-free by injection (same policy as renderer/input.ts): mountMenu takes
// the document and the preload bridge as parameters — production passes the
// real globals in the boot at the bottom, tests pass fakes — so it runs under
// vitest's node environment. The menu NEVER imports electron or net; the
// bridge is its only way out.

import {
  autoParty,
  companionPower,
  companionReincarnationPreview,
  DEFAULT_SAVE,
  format,
  heroForm,
  heroReady,
  heroRerollCost,
  heroRequiredLevel,
  isSpeciesId,
  parseSave,
  PARTY_SIZE,
  pvpParty,
  RELEASES_PER_SOUL,
  SPECIES_IDS,
} from '../core/index.js';
import type { CollectionAction, Companion, SaveFile, SpeciesId } from '../core/index.js';
import { drawSprite, monsterSprites, paletteForTier } from '../renderer/sprites/index.js';
import type { SpriteCanvas } from '../renderer/sprites/index.js';
import type {
  IdentityPayload,
  LeaderboardResult,
  MatchResult,
  NetResult,
  OpponentListResult,
  OpponentSummary,
  PvpResult,
  ReclaimResult,
  Theft,
  TheftsResult,
} from '../shared/api.js';
import {
  battleEnabled,
  canRebirth,
  consumeTargets,
  fuseCandidates,
  leaderboardRows,
  miniRow,
  opponentRows,
  partyPreview,
  pvpResultText,
  rosterRows,
  theftRows,
  togglePick,
} from './view.js';
import type { MiniRow, RankRow, RosterRow, TheftRow } from './view.js';
import { heroPanel, heroCanvas } from './hero.js';
import { mountCodex } from './codex.js';
import { mountShop } from './economy.js';
import { mountProfile } from './profile.js';
import { NICK_RE } from '../shared/api.js';

/** The element surface this page touches — a real DOM element satisfies it. */
export interface MenuElement {
  className: string;
  textContent: string | null;
  hidden: boolean;
  disabled?: boolean;
  /** The name field's text; absent on everything else. */
  value?: string;
  width?: number;
  height?: number;
  /** Native details disclosure state, preserved across live save updates. */
  open?: boolean;
  append(...children: unknown[]): void;
  replaceChildren(...children: unknown[]): void;
  addEventListener(type: 'click' | 'change', listener: () => void): void;
  getContext?(id: '2d'): SpriteCanvas | null;
  setAttribute?(name: string, value: string): void;
  focus?(): void;
}

/** The document surface this page touches — the real `document` satisfies it. */
export interface MenuDocument {
  readonly activeElement?: MenuElement | null;
  createElement(tag: string): MenuElement;
  querySelector(selectors: string): MenuElement | null;
}

/** The slice of window.desmon this page needs (src/renderer/global.d.ts). */
export interface MenuBridge {
  reportMenuReady(): void;
  onSaveFailed?(cb: () => void): () => void;
  onStateChanged(cb: (save: unknown) => void): () => void;
  sendAction(a: CollectionAction): Promise<void>;
  getIdentity(): Promise<IdentityPayload>;
  setName(name: string): Promise<IdentityPayload>;
  getLeaderboard(n?: number): Promise<NetResult<LeaderboardResult>>;
  pvpOpponents?(): Promise<NetResult<OpponentListResult>>;
  pvpMatch(opponentId?: string): Promise<NetResult<MatchResult>>;
  pvp(matchId: string, party: string[]): Promise<NetResult<PvpResult>>;
  thefts(): Promise<NetResult<TheftsResult>>;
  reclaim(theftId: string): Promise<NetResult<ReclaimResult>>;
}

/** Tab ids — each is both the tab button (`#tab-<id>`) and its panel (`#<id>`). */
const PANELS = ['hero', 'shop', 'codex', 'profile', 'roster', 'ranking', 'battle'] as const;

/**
 * Card art: species idle frame at the uniform 1x scale (2026-09-04) on a fixed
 * buffer sized to the LARGEST species, each smaller species centred + bottom-
 * aligned. CSS (`canvas.species`) scales the buffer to the on-screen card, so
 * bigger species read bigger in the menu too.
 */
const CARD_SCALE = 1;
const CARD_W = Math.max(...SPECIES_IDS.map((id) => monsterSprites[id].idle.w));
const CARD_H = Math.max(...SPECIES_IDS.map((id) => monsterSprites[id].idle.h));

/** NICK_RE's ceiling — the name field also carries it as `maxlength`. */
const NAME_MAX = 16;

/** The `#opponent` panel before the first `Find opponent` (F75). */
const NO_OPPONENT = 'No opponent yet';

/** A half-finished two-companion action, waiting for its partner card. */
interface Pending {
  kind: 'consume' | 'fuse';
  id: string;
}

/** Species art key for a runtime species id (unknown ids fall back to slime). */
function speciesKey(speciesId: string): SpeciesId {
  return isSpeciesId(speciesId) ? speciesId : SPECIES_IDS[0];
}

/**
 * Bind the Collection & Battle page: boot reports the menu ready, every
 * `desmon:state-changed` re-renders the roster, and the card buttons send
 * consume/fuse/reincarnate/sacrifice/rebirth back through the bridge.
 * Ranking loads on tab open; Battle names the player, finds an opponent
 * (`pvpMatch`), edits the party and fights it (`pvp`), then plays the theft
 * inbox — all of them take the identity's `online` flag as their offline
 * answer, so a server-less build never calls the network. Roster changes the
 * server made (`removed`, the stolen companion, a reclaim) reach the game ONLY
 * from here, as actions.
 */
export function mountMenu(doc: MenuDocument, api: MenuBridge): void {
  const roster = doc.querySelector('#roster');
  const heroEl = doc.querySelector('#hero');
  const shopEl = doc.querySelector('#shop');
  const codexEl = doc.querySelector('#codex');
  const profileStatsEl = doc.querySelector('#profile-stats');
  const nameStatus = doc.querySelector('#name-status');
  const nameSaveBtn = doc.querySelector('#save-name');
  const rebirthBtn = doc.querySelector('#rebirth');
  const result = doc.querySelector('#result');
  const saveStatus = doc.querySelector('#save-status');
  const ranking = doc.querySelector('#ranking');
  const nameField = doc.querySelector('#name');
  const battleBtn = doc.querySelector('#battle-go');
  const findBtn = doc.querySelector('#find');
  const opponentEl = doc.querySelector('#opponent');
  const opponentsEl = doc.querySelector('#opponents');
  const partyEl = doc.querySelector('#party');
  const picksEl = doc.querySelector('#picks');
  const autoBtn = doc.querySelector('#auto');
  const savePartyBtn = doc.querySelector('#save-party');
  const previewEl = doc.querySelector('#preview');
  const theftsEl = doc.querySelector('#thefts');
  // The page ships its own markup (static/menu.html); without it there is
  // nothing to bind and nothing to report ready for.
  if (
    !roster ||
    !rebirthBtn ||
    !result ||
    !ranking ||
    !nameField ||
    !battleBtn ||
    !findBtn ||
    !opponentEl ||
    !partyEl ||
    !picksEl ||
    !autoBtn ||
    !savePartyBtn ||
    !previewEl ||
    !theftsEl
  ) {
    return;
  }

  let save: SaveFile = DEFAULT_SAVE;
  let pending: Pending | null = null;
  let reincarnation: Companion | null = null;
  let rank: NetResult<LeaderboardResult> | null = null;
  /** The previewed opponent — null before `Find opponent`, or once it expired. */
  let match: MatchResult | null = null;
  let opponents: OpponentSummary[] = [];
  let selectedOpponentId: string | null = null;
  let directoryNote = '상대 목록을 불러오세요.';
  let directoryLoading = false;
  let matchLoading = false;
  let battleLoading = false;
  /** What the `#opponent` panel says while no match is loaded. */
  let opponentNote = NO_OPPONENT;
  /** Use the server's existing expiry boundary; never send a stale preview. */
  const expireMatch = (): boolean => {
    if (match === null || Date.now() <= match.expiresAt) return false;
    match = null;
    selectedOpponentId = null;
    opponentNote = 'Opponent expired — find again';
    return true;
  };
  /** The ids picked for my party, and the saved party they were synced from. */
  let picked: string[] = [];
  let syncedIds = '';
  let inbox: readonly Theft[] = [];
  /** Seconds left on the PvP cooldown; `ticker` runs while it counts down. */
  let cooldown = 0;
  let ticker: unknown = null;
  // One identity call per page: its `name` fills the field and its `online`
  // decides whether a tab may touch the network at all.
  const identity = api.getIdentity();

  const tabs = PANELS.map((id) => ({
    id,
    tab: doc.querySelector(`#tab-${id}`),
    panel: doc.querySelector(`#${id}`),
  }));
  for (const t of tabs) {
    t.tab?.addEventListener('click', () => {
      for (const other of tabs) {
        if (other.tab) other.tab.className = other.id === t.id ? 'tab active' : 'tab';
        other.tab?.setAttribute?.('aria-selected', String(other.id === t.id));
        if (other.panel) other.panel.hidden = other.id !== t.id;
      }
      if (t.id === 'ranking') openRanking();
      if (t.id === 'battle') {
        loadThefts();
        if (api.pvpOpponents) loadOpponents();
      }
      render();
    });
  }

  const span = (className: string, text: string): MenuElement => {
    const e = doc.createElement('span');
    e.className = className;
    e.textContent = text;
    return e;
  };

  const div = (className: string, ...children: MenuElement[]): MenuElement => {
    const e = doc.createElement('div');
    e.className = className;
    e.append(...children);
    return e;
  };

  // Autosaves update numbers frequently. Keep the gallery and actionable
  // choices mounted so scrolling, keyboard focus and an open details survive.
  const heroSections = heroEl ? [div('hero-heading'), div('hero-controls')] : [];
  heroEl?.replaceChildren(...heroSections);
  let heroControlsKey = '';
  let rosterKey = '';

  // A disabled button carries no listener: the page re-renders after every
  // action, so a stale handler can never fire.
  const button = (label: string, disabled: boolean, onClick: () => void): MenuElement => {
    const b = doc.createElement('button');
    b.className = 'btn';
    b.textContent = label;
    b.disabled = disabled;
    if (!disabled) b.addEventListener('click', onClick);
    return b;
  };

  const send = (a: CollectionAction): void => {
    pending = null;
    reincarnation = null;
    result.textContent = '';
    void api.sendAction(a).catch(() => { result.textContent = '요청을 보내지 못했습니다. 다시 시도해 주세요.'; });
    render();
  };
  const updateCodex = codexEl ? mountCodex(doc, codexEl, send) : undefined;
  const updateShop = shopEl ? mountShop(doc, shopEl, send) : undefined;
  const updateProfile = profileStatsEl ? mountProfile(doc, profileStatsEl) : undefined;

  const select = (kind: Pending['kind'], row: RosterRow, hint: string): void => {
    pending = { kind, id: row.id };
    result.textContent = `${hint} ${row.name}.`;
    render();
  };

  const cancel = (): void => {
    pending = null;
    reincarnation = null;
    result.textContent = '';
    render();
  };

  const speciesCanvas = (row: { speciesId: string; stars: number }): MenuElement => {
    const canvas = doc.createElement('canvas');
    canvas.className = 'species';
    canvas.width = CARD_W;
    canvas.height = CARD_H;
    const ctx = canvas.getContext?.('2d');
    if (ctx) {
      const idle = monsterSprites[speciesKey(row.speciesId)].idle;
      // Stars are the card's palette tier, the way monster tiers tint the
      // overlay art (GAME_ARCHITECTURE §4); DrawSpriteOptions has no palette.
      const tinted = { ...idle, palette: paletteForTier(idle.palette, row.stars) };
      const dx = Math.floor((CARD_W - idle.w) / 2);
      drawSprite(ctx, tinted, 0, dx, CARD_H - idle.h, { scale: CARD_SCALE });
    }
    return canvas;
  };

  /** The companion behind a card — its type badge comes from the live roster. */
  const byId = (id: string): Companion | undefined => save.companions.find((c) => c.id === id);
  const matchesConfirmation = (expected: Companion): boolean => {
    const current = byId(expected.id);
    return current !== undefined && current.speciesId === expected.speciesId && current.bossIndex === expected.bossIndex &&
      current.level === expected.level && current.stars === expected.stars;
  };

  /** The saved PvP party (auto until the player saves one of their own). */
  const savedParty = (): Companion[] => pvpParty(save.companions, save.pvpParty, save.hero?.equipped);

  const card = (row: RosterRow): MenuElement => {
    const c = byId(row.id);
    const isPending = pending?.id === row.id;
    const busy = pending !== null || reincarnation !== null;
    const fusable = fuseCandidates(save).some(([a, b]) =>
      pending === null ? a === row.id || b === row.id : isPair(pending.id, row.id, a, b),
    );

    const consume =
      pending?.kind === 'consume'
        ? isPending
          ? button('Cancel', false, cancel)
          : button('Feed', !consumeTargets(save, row.id).includes(pending.id), () => {
              if (pending) send({ type: 'consume', targetId: pending.id, foodId: row.id });
            })
        : button('Consume', busy || !save.companions.some((food) => consumeTargets(save, food.id).includes(row.id)), () => {
            select('consume', row, 'Pick a companion to feed to');
          });

    const fuse =
      pending?.kind === 'fuse'
        ? isPending
          ? button('Cancel', false, cancel)
          : button('Fuse!', !fusable, () => {
              if (pending) send({ type: 'fuse', aId: pending.id, bId: row.id });
            })
        : button('Fuse', busy || !fusable, () => {
            select('fuse', row, 'Pick the twin of');
          });

    const buttons = div(
      'row',
      consume,
      fuse,
      button('Reincarnate', busy || !row.maxLevel, () => {
        const current = byId(row.id);
        if (pending || reincarnation || !current || !companionReincarnationPreview(current)) return;
        reincarnation = { ...current };
        result.textContent = '';
        render();
      }),
      button('Sacrifice', busy, () => {
        send({ type: 'sacrifice', id: row.id });
      }),
    );

    const el = doc.createElement('div');
    el.className = 'card';
    el.append(
      speciesCanvas(row),
      span('name', row.name),
      span('stars', row.starText),
      span('power', row.power),
      // v3 (F75): the elemental badge, and the mark of a PvP party member.
      ...(c ? [span(miniRow(c).typeClass, miniRow(c).typeBadge)] : []),
      ...(savedParty().some((m) => m.id === row.id) ? [span('pvp-mark', '★ PvP')] : []),
      buttons,
    );
    const expected = reincarnation;
    const preview = expected?.id === row.id && c ? companionReincarnationPreview(c) : null;
    if (expected && preview) {
      const power = span('reincarnation-power', `기본 힘 ${format(preview.beforePower)} → ${format(preview.afterPower)}`);
      power.setAttribute?.('title', `${preview.beforePower} → ${preview.afterPower}`);
      power.setAttribute?.('aria-label', `기본 힘 ${preview.beforePower}에서 ${preview.afterPower}로 변경`);
      el.append(div('row reincarnation-confirmation',
        span('reincarnation-result', `${row.name} · Lv.${expected.level} → Lv.${preview.level} · ★${expected.stars} → ★${preview.stars}`),
        power,
        span('muted', '환생하면 레벨이 초기화되어 기본 힘이 감소합니다.'),
        button('환생 확인', false, () => {
          if (reincarnation !== expected) return;
          if (!matchesConfirmation(expected)) {
            reincarnation = null;
            result.textContent = '동료가 변경되어 환생 확인을 취소했습니다. 다시 확인해 주세요.';
            render();
            return;
          }
          const { speciesId, bossIndex, level, stars } = expected;
          send({ type: 'reincarnate', id: expected.id, expected: { speciesId, bossIndex, level, stars } });
        }),
        button('취소', false, () => { if (reincarnation === expected) cancel(); }),
      ));
    }
    return el;
  };

  /**
   * A full roster used to swallow captures in silence. Say what the releases
   * already paid, and put the single obvious trade — the weakest keeper —
   * one click away, without choosing it for the player.
   */
  const rosterFullNotice = (rows: readonly RosterRow[]): MenuElement[] => {
    const released = save.releasedCount ?? 0;
    const weakest = rows.reduce((min: RosterRow | undefined, row) => {
      const c = byId(row.id);
      const m = min ? byId(min.id) : undefined;
      return c && (!m || companionPower(c) < companionPower(m)) ? row : min;
    }, undefined);
    return [
      span('muted', `동료 30/30 · 보관함이 가득 찼습니다. 가득 찬 뒤 놓아준 보스 ${released}마리가 영혼 ${Math.floor(released / RELEASES_PER_SOUL)}을 남겼습니다. Consume / Fuse / Sacrifice로 자리를 만들면 새 보스 동료를 포획할 수 있습니다.`),
      ...(weakest
        ? [div('row', button(`가장 약한 ${weakest.name} 방출`, pending !== null || reincarnation !== null, () => {
            send({ type: 'sacrifice', id: weakest.id });
          }))]
        : []),
    ];
  };

  const rankRow = (r: RankRow): MenuElement => {
    // ponytail: the leaderboard borrows the card's styled columns — `.power`
    // is the right-aligned number, `.stars` the small badge — instead of new CSS.
    return div(
      'row',
      span('rank', r.rank),
      span('name', r.name),
      span('power', r.deepest),
      span('stars', r.rebirths),
    );
  };

  /** A `.card.mini`; `pick` makes it a roster toggle button (F75 §3). */
  const miniCard = (m: MiniRow, pick = false): MenuElement => {
    const el = doc.createElement(pick ? 'button' : 'div');
    el.className = pick && picked.includes(m.id) ? 'card mini pick selected' : pick ? 'card mini pick' : 'card mini';
    el.append(
      speciesCanvas(m),
      span('name', m.name),
      span('stars', m.starText),
      span(m.typeClass, m.typeBadge),
    );
    if (pick) {
      el.addEventListener('click', () => {
        picked = togglePick(picked, m.id);
        render();
      });
    }
    return el;
  };

  // Native buttons retain Tab/Shift+Tab and Enter/Space behavior. Keep them mounted
  // and use aria-disabled during requests so the focused selection is not detached.
  const directoryRows = new Map<string, { row: MenuElement; select: MenuElement; update: (opponent: OpponentSummary) => void }>();
  const directoryStatus = span('muted', directoryNote);
  let directoryIds = '';
  const renderDirectory = (): void => {
    if (!opponentsEl) return;
    const focusedId = [...directoryRows].find(([, nodes]) => nodes.select === doc.activeElement)?.[0];
    for (const id of directoryRows.keys()) {
      if (!opponents.some(opponent => opponent.playerId === id)) directoryRows.delete(id);
    }
    for (const opponent of opponents) {
      const id = opponent.playerId;
      if (!directoryRows.has(id)) {
        const art = span('opponent-hero', '');
        const name = span('name', '');
        const heroName = span('opponent-hero-name', '');
        const record = span('record', '');
        const depth = span('muted', '');
        const party = div('party');
        const select = button('상대 선택 · 파티 미리보기', false, () => {
          if (directoryRows.get(id)?.select === select && !directoryLoading && !matchLoading && !battleLoading) find(id);
        });
        const row = div('opponent-card', art, name, heroName, record, depth, party, select);
        row.setAttribute?.('data-player-id', id);
        let contentKey = '';
        directoryRows.set(id, { row, select, update(next) {
          const key = JSON.stringify(next);
          if (contentKey !== key) {
            contentKey = key;
            art.replaceChildren(heroCanvas(doc, next.hero.formId, 64));
            name.textContent = `#${next.rank} ${next.name}`;
            heroName.textContent = heroForm(next.hero.formId)?.name ?? '수습 영웅';
            record.textContent = `${next.wins}승 ${next.losses}패`;
            depth.textContent = `최고 몬스터 ${next.bestIndex}`;
            party.replaceChildren(...(next.party.length ? next.party.map(c => miniCard(miniRow(c))) : [span('muted', '동료 파티 없음')]));
            select.setAttribute?.('aria-label', `#${next.rank} ${next.name} · 상대 선택 · 파티 미리보기`);
          }
          const selected = selectedOpponentId === id;
          row.className = `opponent-card${selected ? ' selected' : ''}`;
          select.textContent = selected ? matchLoading ? '선택한 상대 · 불러오는 중…' : '선택한 상대 · 파티 미리보기' : '상대 선택 · 파티 미리보기';
          select.setAttribute?.('aria-pressed', String(selected));
          select.setAttribute?.('aria-disabled', String(directoryLoading || matchLoading || battleLoading));
        } });
      }
      directoryRows.get(id)!.update(opponent);
    }
    directoryStatus.textContent = directoryNote;
    const ids = JSON.stringify(opponents.map(opponent => opponent.playerId));
    if (directoryIds !== ids) {
      directoryIds = ids;
      opponentsEl.replaceChildren(...(opponents.length ? opponents.map(opponent => directoryRows.get(opponent.playerId)!.row) : [directoryStatus]));
      if (focusedId) (directoryRows.get(focusedId)?.select ?? findBtn).focus?.();
    }
  };

  /** The `#opponent` panel: the previewed party, the bot line, or the note. */
  const opponentPanel = (): MenuElement[] => {
    if (match === null) return [span('name', opponentNote)];
    if (match.bot) return [span('name', 'Training Dummy (no party)')];
    const { name, bestIndex, rebirths } = match.opponent;
    return [
      ...(match.opponent.hero ? [heroCanvas(doc, match.opponent.hero.formId)] : []),
      span('name', name),
      span('power', `Monster ${String(bestIndex)}`),
      span('stars', `♻×${String(rebirths)}`),
      div('party', ...opponentRows(match).map((m) => miniCard(m))),
    ];
  };

  const theftRow = (t: TheftRow): MenuElement =>
    div(
      'row',
      span('name', t.text),
      button('Reclaim', false, () => {
        reclaim(t.id);
      }),
    );

  const render = (): void => {
    expireMatch();
    if (heroEl) {
      const parts = heroPanel(doc, save, send);
      heroSections[0]?.replaceChildren(parts[0]);
      const controlsKey = JSON.stringify([save.hero?.choices, save.hero?.collection, save.hero?.offerSerial,
        save.hero?.reincarnations, save.hero?.deferRemainingMs, save.hero?.restRemainingMs,
        heroReady(save.level, save.hero), save.level >= heroRequiredLevel(save.hero?.reincarnations ?? 0), Math.min(save.coins, heroRerollCost(save.hero?.reincarnations ?? 0))]);
      if (controlsKey !== heroControlsKey) {
        heroControlsKey = controlsKey;
        heroSections[1]?.replaceChildren(parts[1]);
      }
    }
    updateShop?.(save);
    updateCodex?.(save);
    updateProfile?.(save);
    // Keep an unchanged confirmation mounted during frequent save updates.
    const nextRosterKey = JSON.stringify([save.companions, save.pvpParty, save.hero?.equipped,
      save.releasedCount, pending, reincarnation]);
    if (rosterKey !== nextRosterKey) {
      rosterKey = nextRosterKey;
      const rows = rosterRows(save);
      roster.replaceChildren(
        ...(rows.length >= 30 ? rosterFullNotice(rows) : []),
        ...(rows.length === 0
          ? [span('row', 'No companions yet — beat a boss to capture one.')]
          : rows.map(card)),
      );
    }
    rebirthBtn.disabled = !canRebirth(save);
    ranking.replaceChildren(...(rank === null ? [] : leaderboardRows(rank).map(rankRow)));

    // Battle tab (F75): opponent preview, party editor, live preview, inbox.
    opponentEl.replaceChildren(...opponentPanel());
    findBtn.disabled = matchLoading || battleLoading;
    findBtn.setAttribute?.('aria-disabled', String(directoryLoading || matchLoading || battleLoading));
    renderDirectory();
    partyEl.replaceChildren(
      ...Array.from({ length: PARTY_SIZE }, (_, i) => {
        const c = picked[i] === undefined ? undefined : byId(picked[i]);
        return div('slot', ...(c ? [miniCard(miniRow(c))] : []));
      }),
    );
    picksEl.replaceChildren(...save.companions.map((c) => miniCard(miniRow(c), true)));
    previewEl.textContent = partyPreview(
      picked.flatMap((id) => byId(id) ?? []),
      match?.opponent.party ?? [],
      save.hero?.equipped,
    );
    theftsEl.replaceChildren(...theftRows(inbox, Date.now()).map(theftRow));
    battleBtn.textContent = cooldown > 0 ? `Battle! (${String(cooldown)}s)` : 'Battle!';
    battleBtn.disabled = directoryLoading || battleLoading || matchLoading || !battleEnabled({ match, party: picked, cooldownUntil: cooldown });
  };

  /** Fire-and-forget bridge call: a rejected invoke must not break the page. */
  const settle = <T>(p: Promise<T>, use: (value: T) => void): void => {
    void p.then(use, () => undefined);
  };

  /** Run `fn` only when the server is reachable; otherwise answer `offline`. */
  const online = (fn: () => void, offline: () => void): void => {
    void identity.then(id => { if (id.online) fn(); else offline(); }, offline);
  };

  /** The server stripped these companions from my roster — tell the game. */
  const forwardRemoved = (removed: string[]): void => {
    if (removed.length > 0) void api.sendAction({ type: 'removeCompanions', ids: removed });
  };

  /** Client countdown from the server's retryAfterSec; 0 re-arms the button. */
  const startCooldown = (sec: number): void => {
    cooldown = Math.max(0, Math.ceil(sec));
    if (cooldown === 0 || ticker !== null) return;
    ticker = setInterval(() => {
      cooldown -= 1;
      if (cooldown <= 0) {
        clearInterval(ticker);
        ticker = null;
      }
      render();
    }, 1000);
  };

  const openRanking = (): void => {
    const show = (r: NetResult<LeaderboardResult>): void => {
      if (r.ok) forwardRemoved(r.value.removed);
      rank = r;
      render();
    };
    online(
      () => {
        settle(api.getLeaderboard(), show);
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
  };

  /** Refresh the directory without leaving a match for a removed opponent armed. */
  const loadOpponents = (): void => {
    if (!api.pvpOpponents || directoryLoading || matchLoading || battleLoading) return;
    directoryLoading = true;
    directoryNote = '상대 목록을 불러오는 중…';
    render();
    const show = (r: NetResult<OpponentListResult>): void => {
      directoryLoading = false;
      opponents = r.ok ? r.value.opponents : [];
      directoryNote = r.ok ? '아직 대전 상대가 없습니다. 나중에 목록을 새로고침하세요.' : '서버에 연결할 수 없습니다. 목록 새로고침으로 다시 시도하세요.';
      if (!r.ok || (selectedOpponentId !== null && !opponents.some(opponent => opponent.playerId === selectedOpponentId))) {
        match = null;
        selectedOpponentId = null;
        opponentNote = r.ok ? '선택한 상대가 목록에 없습니다. 목록을 새로고침하고 다시 선택하세요.' : directoryNote;
      }
      render();
    };
    online(() => { void api.pvpOpponents!().then(show, () => show({ ok: false, error: 'network' })); },
      () => show({ ok: false, error: 'offline' }));
  };

  const find = (opponentId?: string): void => {
    if (directoryLoading || matchLoading || battleLoading || (opponentId !== undefined && !opponents.some(opponent => opponent.playerId === opponentId))) return;
    matchLoading = true;
    match = null;
    selectedOpponentId = opponentId ?? null;
    opponentNote = '상대 미리보기를 불러오는 중…';
    const show = (r: NetResult<MatchResult>): void => {
      matchLoading = false;
      const mismatch = r.ok && opponentId !== undefined && (r.value.bot || r.value.opponent.playerId !== opponentId);
      match = r.ok && !mismatch ? r.value : null;
      if (match) { opponentNote = NO_OPPONENT; result.textContent = ''; }
      else {
        selectedOpponentId = null;
        opponentNote = mismatch ? '선택한 상대와 응답이 일치하지 않습니다. 목록을 새로고침하세요.' : '상대를 불러오지 못했습니다. 목록을 새로고침하고 다시 선택하세요.';
        result.textContent = r.ok ? opponentNote : pvpResultText(r);
      }
      render();
      if (!match && opponentId !== undefined && doc.activeElement === directoryRows.get(opponentId)?.select) findBtn.focus?.();
    };
    online(
      () => {
        void api.pvpMatch(opponentId).then(show, () => show({ ok: false, error: 'network' }));
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
    render();
  };

  /**
   * Step 2 (F55/F75 §4): the loaded match plus my picked party. A win only
   * reaches the game from here — `removed` first, then the verdict with the
   * replay the game window plays (F66).
   */
  const pvp = (): void => {
    if (expireMatch()) { render(); findBtn.focus?.(); return; }
    const loaded = match;
    if (loaded === null || directoryLoading || matchLoading || battleLoading) return;
    const selectedId = selectedOpponentId;
    battleLoading = true;
    const show = (r: NetResult<PvpResult>): void => {
      battleLoading = false;
      if (r.ok && selectedId !== null && (r.value.bot || r.value.opponent.playerId !== selectedId)) {
        match = null;
        selectedOpponentId = null;
        opponentNote = '선택한 상대와 전투 결과가 일치하지 않습니다. 목록을 새로고침하세요.';
        result.textContent = opponentNote;
        render();
        findBtn.focus?.();
        return;
      }
      if (r.ok) {
        const { win, stolen, opponent, blows, removed } = r.value;
        forwardRemoved(removed);
        void api.sendAction({
          type: 'pvpResult',
          won: win,
          stolen,
          lostId: null,
          replay: { opponentName: opponent.name, opponentParty: opponent.party, blows,
            ...(opponent.hero ? { opponentHero: opponent.hero } : {}) },
        });
        // The server consumed the match: the next battle needs a new one.
        match = null;
        selectedOpponentId = null;
        opponentNote = NO_OPPONENT;
        loadThefts();
        if (api.pvpOpponents) loadOpponents();
      } else if (r.error === 'cooldown') {
        startCooldown(r.retryAfterSec ?? 0);
      } else {
        match = null;
        selectedOpponentId = null;
        opponentNote = r.error === 'expired' ? 'Opponent expired — find again' : '전투를 완료하지 못했습니다. 상대를 다시 선택하세요.';
      }
      result.textContent = r.ok || r.error !== 'expired' ? pvpResultText(r) : '';
      render();
      if (!r.ok && r.error !== 'cooldown') findBtn.focus?.();
    };
    online(
      () => {
        // The identity promise may settle after the existing match expires.
        if (expireMatch() || match !== loaded) {
          battleLoading = false;
          render();
          findBtn.focus?.();
          return;
        }
        void api.pvp(loaded.matchId, [...picked]).then(show, () => show({ ok: false, error: 'network' }));
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
    render();
  };

  /** The theft inbox (F75 §5) — refreshed on tab open and after every battle. */
  const loadThefts = (): void => {
    const show = (r: NetResult<TheftsResult>): void => {
      inbox = r.ok ? r.value.thefts : [];
      render();
    };
    online(
      () => {
        settle(api.thefts(), show);
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
  };

  /** Take a stolen companion back: the game gets it as an `addCompanion`. */
  const reclaim = (theftId: string): void => {
    settle(api.reclaim(theftId), (r) => {
      if (r.ok) {
        void api.sendAction({ type: 'addCompanion', companion: r.value.companion });
        loadThefts();
        return;
      }
      // Only a settled window drops the row; a network hiccup keeps it.
      if (r.error === 'expired' || r.error === 'gone') {
        inbox = inbox.filter((t) => t.id !== theftId);
        result.textContent =
          r.error === 'expired' ? 'Too late — the reclaim window closed.' : 'Gone — the thief no longer has it.';
      }
      render();
    });
  };

  rebirthBtn.addEventListener('click', () => {
    if (canRebirth(save)) send({ type: 'rebirth' });
  });

  findBtn.addEventListener('click', () => { if (api.pvpOpponents) loadOpponents(); else find(); });

  battleBtn.addEventListener('click', () => {
    if (battleEnabled({ match, party: picked, cooldownUntil: cooldown })) pvp();
  });

  autoBtn.addEventListener('click', () => {
    picked = autoParty(save.companions, save.hero?.equipped).map((c) => c.id);
    render();
  });

  savePartyBtn.addEventListener('click', () => {
    void api.sendAction({ type: 'setPvpParty', ids: [...picked] });
    render();
  });

  // The field is the only writer of the name; main validates and answers with
  // the identity it kept, so the field always shows what the server will see.
  let namePending = false;
  let editedName = false;
  const saveName = (): void => {
    editedName = true;
    const proposed = (nameField.value ?? '').slice(0, NAME_MAX);
    if (namePending) return;
    if (!NICK_RE.test(proposed)) {
      if (nameStatus) nameStatus.textContent = '영문·숫자·_·-를 사용해 1–16자로 입력하세요.';
      return;
    }
    namePending = true;
    if (nameSaveBtn) nameSaveBtn.disabled = true;
    if (nameStatus) nameStatus.textContent = '이름 저장 중…';
    void api.setName(proposed).then((id) => {
      // A reply for an older edit must not overwrite what the player is typing now.
      if ((nameField.value ?? '').slice(0, NAME_MAX) === proposed) nameField.value = id.name;
      if (nameStatus) nameStatus.textContent = id.name === proposed ? '이름을 저장했습니다.' : '이름을 저장하지 못했습니다. 다시 시도하세요.';
    }, () => {
      if (nameStatus) nameStatus.textContent = '이름을 저장하지 못했습니다. 다시 시도하세요.';
    }).finally(() => {
      namePending = false;
      if (nameSaveBtn) nameSaveBtn.disabled = false;
    });
  };
  nameField.addEventListener('change', saveName);
  nameSaveBtn?.addEventListener('click', saveName);

  settle(identity, (id) => {
    if (!editedName && !nameField.value) nameField.value = id.name;
  });

  let saveFailed = false;
  api.onSaveFailed?.(() => {
    saveFailed = true;
    const status = saveStatus ?? result;
    status.hidden = false;
    status.textContent = '저장하지 못했습니다. 앱을 닫지 말고 다시 시도해 주세요.';
  });
  api.onStateChanged((raw) => {
    if (saveFailed) {
      if (saveStatus) { saveStatus.hidden = true; saveStatus.textContent = ''; }
      else result.textContent = '';
      saveFailed = false;
    }
    // Trust boundary: the payload is whatever main read off disk.
    save = parseSave(raw);
    pending = null;
    if (reincarnation && !matchesConfirmation(reincarnation)) {
      reincarnation = null;
      result.textContent = '동료가 변경되어 환생 확인을 취소했습니다. 다시 확인해 주세요.';
    }
    // Re-seed the editor only when the SAVED party moved: an autosave must not
    // throw away the picks the player is still editing.
    const ids = savedParty().map((c) => c.id);
    if (ids.join(',') !== syncedIds) {
      syncedIds = ids.join(',');
      picked = ids;
    }
    render();
  });

  render();
  api.reportMenuReady();
}

/** True when the unordered pair {x, y} is the unordered pair {a, b}. */
function isPair(x: string, y: string, a: string, b: string): boolean {
  return (a === x && b === y) || (a === y && b === x);
}

// Boot. `document`/`window` are declared locally (module scope) so this file
// also compiles in the DOM-free test project, and the typeof guard keeps it
// importable from vitest's node environment.
declare const document: MenuDocument;
declare const window: { desmon: MenuBridge };
// Declared locally too: the DOM and node lib types disagree on the handle.
declare const setInterval: (cb: () => void, ms: number) => unknown;
declare const clearInterval: (handle: unknown) => void;

if (typeof document !== 'undefined') {
  mountMenu(document, window.desmon);
}

// Net client + net session (SPEC F48; SERVER_ARCHITECTURE §6). Electron-free:
// `fetch`, the userData directory and randomUUID are injected, so the whole
// module is testable with a fake fetch and a tmp directory. Nothing here ever
// throws — a sleeping dyno, a dead network or a garbage body must never break
// the game, which never waits on any of this.

import type {
  ApiError,
  Companion,
  HeroAppearance,
  IdentityPayload,
  LeaderboardResponse,
  LeaderboardResult,
  MatchResponse,
  MatchResult,
  NetResult,
  OpponentListResult,
  PvpRequest,
  PvpResponse,
  PvpResult,
  ReclaimResponse,
  ReclaimResult,
  RegisterResponse,
  Snapshot,
  SnapshotResponse,
  TheftsResponse,
  TheftsResult,
} from '../shared/api.js';
import { isValidName, parsePvpHistory, readIdentity, recordPvpHistory, writeIdentity, type Identity } from './identity.js';
import { isHeroRoll } from '../core/hero.js';
import { SPECIES_IDS } from '../core/monsters.js';
import { COMPANION_ID_RE, INT_MAX, LEADERBOARD_MAX, LEVEL_MAX, NICK_RE, PARTY_SIZE_MAX, THEFTS_MAX } from '../shared/api.js';

/** Every request is abandoned after this long (Render's free tier cold-starts). */
export const NET_TIMEOUT_MS = 5000;

export interface NetClient {
  register(name: string): Promise<NetResult<RegisterResponse>>;
  upload(token: string, snapshot: Snapshot): Promise<NetResult<SnapshotResponse>>;
  leaderboard(token: string | null, n: number): Promise<NetResult<LeaderboardResponse>>;
  opponents(token: string): Promise<NetResult<OpponentListResult>>;
  match(token: string, opponentId?: string): Promise<NetResult<MatchResponse>>;
  pvp(token: string, body: PvpRequest): Promise<NetResult<PvpResponse>>;
  thefts(token: string): Promise<NetResult<TheftsResponse>>;
  reclaim(token: string, theftId: string): Promise<NetResult<ReclaimResponse>>;
}

/** Structural view of the parts of a save the server ranks. SaveFileV2 is assignable. */
export interface SnapshotSource {
  bestIndex: number;
  rebirths: number;
  companions: Companion[];
  /** ponytail: optional because src/server/probe.ts snapshots a party-less player. */
  pvpParty?: string[];
  hero?: { equipped: HeroAppearance };
}

export interface NetSession {
  identity(): IdentityPayload;
  pvpHistory(): { wins: number; losses: number };
  setName(name: unknown): IdentityPayload;
  onSave(save: SnapshotSource): void;
  leaderboard(n: number): Promise<NetResult<LeaderboardResult>>;
  opponents(): Promise<NetResult<OpponentListResult>>;
  match(opponentId?: string): Promise<NetResult<MatchResult>>;
  pvp(matchId: string, party: string[]): Promise<NetResult<PvpResult>>;
  thefts(): Promise<NetResult<TheftsResult>>;
  reclaim(theftId: string): Promise<NetResult<ReclaimResult>>;
}

/** The wire snapshot for `save` under `name`. */
export function toSnapshot(name: string, save: SnapshotSource): Snapshot {
  return {
    name,
    bestIndex: save.bestIndex,
    rebirths: save.rebirths,
    companions: save.companions,
    party: save.pvpParty ?? [],
    ...(save.hero ? { hero: save.hero.equipped } : {}),
  };
}

/** JSON body of `res`, or undefined when it is missing/unparsable (never throws). */
async function readJson(res: Response): Promise<unknown> {
  try {
    return (await res.json()) as unknown;
  } catch {
    return undefined;
  }
}

const object = (v: unknown): Record<string, unknown> | null =>
  typeof v === 'object' && v !== null && !Array.isArray(v) ? v as Record<string, unknown> : null;
const integer = (v: unknown, min = 0, max = INT_MAX): boolean =>
  typeof v === 'number' && Number.isSafeInteger(v) && v >= min && v <= max;
const playerId = (v: unknown): boolean => typeof v === 'string' && /^[A-Za-z0-9-]{1,64}$/.test(v);
const companionId = (v: unknown): boolean => typeof v === 'string' && COMPANION_ID_RE.test(v);

/** All companion-bearing replies cross this boundary before reaching saves or sprites. */
function isCompanion(value: unknown): boolean {
  const c = object(value);
  return !!c && companionId(c['id']) &&
    typeof c['speciesId'] === 'string' && (SPECIES_IDS as readonly string[]).includes(c['speciesId']) &&
    integer(c['bossIndex']) && integer(c['level'], 1, LEVEL_MAX) && integer(c['stars']);
}

function isOpponent(value: unknown): boolean {
  const row = object(value);
  if (!row || (row['playerId'] !== undefined && !playerId(row['playerId'])) ||
    typeof row['name'] !== 'string' || !(NICK_RE.test(row['name']) || row['name'] === 'Training Dummy') ||
    !integer(row['bestIndex']) || !integer(row['rebirths']) ||
    (row['hero'] !== undefined && !isHeroRoll(row['hero']))) return false;
  const party = row['party'];
  return Array.isArray(party) && party.length <= PARTY_SIZE_MAX && party.every(isCompanion) &&
    new Set(party.map((c: Companion) => c.id)).size === party.length;
}

function isOpponentList(value: unknown): boolean {
  const rows = object(value)?.['opponents'];
  return Array.isArray(rows) && rows.length <= LEADERBOARD_MAX && rows.every((entry) => {
    const row = object(entry);
    return !!row && isOpponent(row) && playerId(row['playerId']) &&
      typeof row['name'] === 'string' && NICK_RE.test(row['name']) && isHeroRoll(row['hero']) &&
      integer(row['rank'], 1) && integer(row['wins']) && integer(row['losses']);
  });
}

function isThefts(value: unknown): boolean {
  return Array.isArray(value) && value.length <= THEFTS_MAX && value.every((entry) => {
    const theft = object(entry);
    return !!theft && companionId(theft['id']) && isCompanion(theft['companion']) &&
      companionId(theft['transferredId']) && playerId(theft['thiefId']) &&
      typeof theft['thiefName'] === 'string' && NICK_RE.test(theft['thiefName']) &&
      integer(theft['at'], 0, Number.MAX_SAFE_INTEGER) && integer(theft['reclaimUntil'], 0, Number.MAX_SAFE_INTEGER);
  });
}

function isSnapshotResponse(value: unknown): boolean {
  const row = object(value);
  return !!row && integer(row['rank'], 1) && Array.isArray(row['removed']) &&
    row['removed'].every(companionId) && isThefts(row['thefts']);
}

function isMatchResponse(value: unknown): boolean {
  const row = object(value);
  return !!row && playerId(row['matchId']) && integer(row['seed'], 0, 0xffffffff) &&
    typeof row['bot'] === 'boolean' && isOpponent(row['opponent']) &&
    integer(row['expiresAt'], 0, Number.MAX_SAFE_INTEGER);
}

function isPvpResponse(value: unknown): boolean {
  const row = object(value);
  return !!row && typeof row['bot'] === 'boolean' && typeof row['win'] === 'boolean' &&
    integer(row['seed'], 0, 0xffffffff) && isOpponent(row['opponent']) &&
    (row['stolen'] === null || isCompanion(row['stolen'])) &&
    (row['lost'] === null || isCompanion(row['lost'])) &&
    Array.isArray(row['blows']) && row['blows'].every((entry) => {
      const blow = object(entry);
      return !!blow && (blow['side'] === 'A' || blow['side'] === 'D') &&
        companionId(blow['actorId']) && companionId(blow['targetId']) &&
        typeof blow['damage'] === 'string' && /^\d+$/.test(blow['damage']) && typeof blow['ko'] === 'boolean';
    });
}

/**
 * HTTP client for `/v1` (SERVER_ARCHITECTURE §3). `baseUrl === ''` means
 * offline: every method resolves `{ ok: false, error: 'offline' }` and fetch is
 * never called.
 */
export function createNetClient(o: {
  baseUrl: string;
  fetchFn?: typeof fetch;
  timeoutMs?: number;
}): NetClient {
  const { baseUrl, fetchFn = fetch, timeoutMs = NET_TIMEOUT_MS } = o;

  async function call<T>(
    method: string,
    path: string,
    token: string | null,
    body?: unknown,
    validate?: (value: unknown) => boolean,
  ): Promise<NetResult<T>> {
    if (baseUrl === '') return { ok: false, error: 'offline' };
    let res: Response;
    try {
      res = await fetchFn(`${baseUrl}${path}`, {
        method,
        headers: token === null
          ? { 'content-type': 'application/json' }
          : { 'content-type': 'application/json', authorization: `Bearer ${token}` },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(timeoutMs),
      });
    } catch {
      return { ok: false, error: 'network' };
    }
    if (res.status === 401) return { ok: false, error: 'unauthorized' };
    // v3: a dead match / a closed reclaim window, and a companion the thief no
    // longer holds — both are normal outcomes the menu explains, not failures.
    if (res.status === 410) return { ok: false, error: 'expired', status: 410 };
    if (res.status === 409) return { ok: false, error: 'gone', status: 409 };
    const parsed = await readJson(res);
    if (res.ok && parsed !== undefined) {
      return !validate || validate(parsed) ? { ok: true, value: parsed as T } : { ok: false, error: 'server' };
    }
    const error = (typeof parsed === 'object' && parsed !== null ? parsed : {}) as ApiError;
    if (res.status === 429 && error.error === 'cooldown') {
      return { ok: false, error: 'cooldown', retryAfterSec: error.retryAfterSec };
    }
    return { ok: false, error: 'server', status: res.status };
  }

  return {
    register: (name) => call<RegisterResponse>('POST', '/v1/players', null, { nickname: name }),
    upload: (token, snapshot) => call<SnapshotResponse>('PUT', '/v1/snapshot', token, snapshot, isSnapshotResponse),
    leaderboard: (token, n) => call<LeaderboardResponse>('GET', `/v1/leaderboard?n=${n}`, token),
    opponents: (token) => call<OpponentListResult>('GET', '/v1/pvp/opponents', token, undefined, isOpponentList),
    match: async (token, opponentId) => {
      const result = await call<MatchResponse>('POST', '/v1/pvp/match', token, { opponentId }, isMatchResponse);
      if (result.ok && opponentId !== undefined && (result.value.bot || result.value.opponent.playerId !== opponentId)) {
        return { ok: false, error: 'server' };
      }
      return result;
    },
    pvp: (token, body) => call<PvpResponse>('POST', '/v1/pvp', token, body, isPvpResponse),
    thefts: (token) => call<TheftsResponse>('GET', '/v1/thefts', token, undefined, (value) => isThefts(object(value)?.['thefts'])),
    reclaim: (token, theftId) => call<ReclaimResponse>('POST', '/v1/reclaim', token, { theftId }, (value) => isCompanion(object(value)?.['companion'])),
  };
}

/**
 * Owns identity.json, lazy registration, the dirty roster key, the sync moments
 * and the once-per-session re-register after a 401 (SERVER_ARCHITECTURE §6).
 */
export function createNetSession(deps: {
  client: NetClient;
  userDataDir: string;
  online: boolean;
  randomUUID: () => string;
}): NetSession {
  const { client, userDataDir, online, randomUUID } = deps;
  let identity: Identity = readIdentity(userDataDir, randomUUID);
  let historyDirty = false;
  /** Last save handed to the session; the source of every upload. */
  let lastSave: SnapshotSource | null = null;
  /** Roster key the server already has; null = nothing uploaded yet. */
  let syncedKey: string | null = null;
  let reRegistered = false;
  /** Keep bindings for retries and concurrent callbacks throughout this session. */
  const selectedOpponents = new Map<string, string>();

  /** bestIndex is deliberately absent: kills at the frontier must not spam PUTs. */
  const rosterKey = (save: SnapshotSource): string =>
    JSON.stringify([identity.name, save.rebirths, save.companions, save.pvpParty ?? [], save.hero?.equipped]);

  const payload = (): IdentityPayload => ({ name: identity.name, playerId: identity.playerId, online });

  const store = (next: Identity): void => {
    identity = next;
    writeIdentity(userDataDir, next);
  };

  async function ensureRegistered(): Promise<NetResult<string>> {
    if (identity.token !== null) return { ok: true, value: identity.token };
    const res = await client.register(identity.name);
    if (!res.ok) return res;
    store({ ...identity, playerId: res.value.playerId, token: res.value.token });
    return { ok: true, value: res.value.token };
  }

  /** Registers if needed, then runs `send`; a 401 re-registers and retries ONCE per session. */
  async function withToken<T>(send: (token: string) => Promise<NetResult<T>>): Promise<NetResult<T>> {
    const first = await ensureRegistered();
    if (!first.ok) return first;
    const res = await send(first.value);
    if (res.ok || res.error !== 'unauthorized' || reRegistered) return res;
    reRegistered = true;
    store({ ...identity, playerId: null, token: null });
    const second = await ensureRegistered();
    if (!second.ok) return second;
    return send(second.value);
  }

  async function upload(): Promise<NetResult<SnapshotResponse> | null> {
    if (lastSave === null) return null;
    const key = rosterKey(lastSave);
    const snapshot = toSnapshot(identity.name, lastSave);
    const res = await withToken((token) => client.upload(token, snapshot));
    if (res.ok) syncedKey = key;
    return res;
  }

  const uploadIfDirty = async (): Promise<NetResult<SnapshotResponse> | null> =>
    lastSave !== null && rosterKey(lastSave) !== syncedKey ? upload() : null;

  /** Companion ids the server stripped on the pre-flight upload, for the menu to drop. */
  const removedOf = (res: NetResult<SnapshotResponse> | null): string[] =>
    res !== null && res.ok ? res.value.removed : [];

  return {
    pvpHistory() {
      const history = parsePvpHistory(identity.pvpHistory);
      return { wins: history.wins, losses: history.losses };
    },
    identity() {
      void uploadIfDirty();
      return payload();
    },
    setName(name) {
      if (isValidName(name)) {
        const next = { ...identity, name };
        if (writeIdentity(userDataDir, next)) identity = next;
      }
      return payload();
    },
    onSave(save) {
      if (historyDirty) historyDirty = !writeIdentity(userDataDir, identity);
      lastSave = save;
      void uploadIfDirty();
    },
    async leaderboard(n) {
      const removed = removedOf(await uploadIfDirty());
      const res = await withToken((token) => client.leaderboard(token, n));
      return res.ok ? { ok: true, value: { ...res.value, removed } } : res;
    },
    async opponents() {
      const uploaded = await uploadIfDirty();
      if (uploaded && !uploaded.ok) return uploaded;
      return withToken((token) => client.opponents(token));
    },
    async match(opponentId) {
      // Upload first when dirty: the opponent picker must see my current party.
      const uploaded = await uploadIfDirty();
      if (uploaded && !uploaded.ok) return uploaded;
      const res = await withToken((token) => client.match(token, opponentId));
      if (res.ok && opponentId !== undefined) {
        if (res.value.bot !== false || res.value.opponent?.playerId !== opponentId) return { ok: false, error: 'server' };
        selectedOpponents.set(res.value.matchId, opponentId);
      }
      return res;
    },
    async pvp(matchId, party) {
      const expectedOpponent = selectedOpponents.get(matchId);
      const uploaded = await upload();
      if (uploaded && !uploaded.ok) return uploaded;
      const removed = removedOf(uploaded);
      const res = await withToken((token) => client.pvp(token, { matchId, party }));
      if (res.ok && expectedOpponent !== undefined &&
        (res.value.bot !== false || res.value.opponent?.playerId !== expectedOpponent)) return { ok: false, error: 'server' };
      if (res.ok && res.value?.bot === false && typeof res.value.win === 'boolean') {
        const previous = identity.pvpHistory ?? parsePvpHistory(undefined);
        const next = recordPvpHistory(previous, matchId, res.value.win);
        if (next !== previous) {
          // Synchronous replacement before returning also serializes concurrent
          // callbacks for one match. A failed disk write is reported and retried.
          identity = { ...identity, pvpHistory: next };
          historyDirty = !writeIdentity(userDataDir, identity);
        }
      }
      return res.ok ? { ok: true, value: { ...res.value, removed, ...(historyDirty ? { historySaved: false as const } : {}) } } : res;
    },
    thefts: () => withToken((token) => client.thefts(token)),
    reclaim: (theftId) => withToken((token) => client.reclaim(token, theftId)),
  };
}

import { describe, expect, it } from 'vitest';
import {
  applyCollection, companionPower, companionReincarnationPreview, createEngine, DEFAULT_SAVE,
  isCompanionSnapshot, mulberry32, parseSave, serializeSave,
} from '../src/core/index.js';
import type { Companion, CollectionAction, GameState } from '../src/core/index.js';

const max = Number.MAX_SAFE_INTEGER;
const companion = (id: string, level = 10, stars = 0): Companion =>
  ({ id, speciesId: 'bat', bossIndex: 7, level, stars });
const stateWith = (companions: Companion[]): GameState =>
  createEngine({ ...DEFAULT_SAVE, companions, nextCompanionId: companions.length + 1 }, mulberry32(7)).getState();
const success = (state: GameState, action: CollectionAction): GameState => {
  const result = applyCollection(state, action);
  if ('error' in result) throw new Error(result.error);
  return result.state;
};

describe('v0.7 companion growth and save compatibility', () => {
  it.each([11, 250, max])('round trips Lv%s through JSON, engine save and restart without truncation', level => {
    const c = companion('c1', level);
    const save = parseSave({ ...DEFAULT_SAVE, companions: [c] });
    expect(save.companions).toEqual([c]);
    const engine = createEngine(parseSave(serializeSave(save)), mulberry32(9));
    expect(engine.getState().companions).toEqual([c]);
    const restarted = createEngine(parseSave(serializeSave(engine.toSave())), mulberry32(9));
    expect(restarted.getState().companions).toEqual([c]);
    expect(companionPower(c)).toBe(BigInt(level));
  });

  it.each([0, -1, 1.5, max + 1, Infinity, NaN, '250'])('rejects invalid saved level %s', level => {
    expect(parseSave({ companions: [{ ...companion('c1'), level }] }).companions).toEqual([]);
  });

  it('consumes beyond Lv10 and permits the exact safe-integer boundary', () => {
    const state = stateWith([companion('c1', 250), companion('c2', 1, 3)]);
    expect(success(state, { type: 'consume', targetId: 'c1', foodId: 'c2' }).companions)
      .toEqual([companion('c1', 254)]);
    const boundary = stateWith([companion('c1', max - 1), companion('c2', 1)]);
    expect(success(boundary, { type: 'consume', targetId: 'c1', foodId: 'c2' }).companions)
      .toEqual([companion('c1', max)]);
  });

  it('rejects overflowing level or stars before consuming any companion', () => {
    const cases: [Companion[], CollectionAction][] = [
      [[companion('c1', max), companion('c2', 1)], { type: 'consume', targetId: 'c1', foodId: 'c2' }],
      [[companion('c1', 10), companion('c2', 1, max)], { type: 'consume', targetId: 'c1', foodId: 'c2' }],
      [[companion('c1', 10, max), companion('c2', 10, max)], { type: 'fuse', aId: 'c1', bId: 'c2' }],
      [[companion('c1', 10, max)], { type: 'reincarnate', id: 'c1' }],
    ];
    for (const [companions, action] of cases) {
      const state = stateWith(companions), before = structuredClone(state);
      expect(applyCollection(state, action)).toHaveProperty('error');
      expect(state).toEqual(before);
    }
    // Overflow is rejected before attempting an enormous bigint exponent.
    expect(companionReincarnationPreview(companion('c1', 10, max))).toBeNull();
  });

  it.each([10, 11, 250, max])('reincarnates Lv%s to Lv1/stars+1 with exact before/after power', level => {
    const c = companion('c1', level, 2), preview = companionReincarnationPreview(c);
    expect(preview).toEqual({ level: 1, stars: 3, beforePower: BigInt(level) * 4n, afterPower: 8n });
    const state = success(stateWith([c]), { type: 'reincarnate', id: c.id, expected: c });
    expect(state.companions).toEqual([companion('c1', 1, 3)]);
    expect(companionPower(state.companions[0]!) * BigInt(level)).toBe(companionPower(c) * 2n);
  });

  it('rejects Lv9 and stale, malformed, missing-target or reused confirmations without mutation', () => {
    expect(companionReincarnationPreview(companion('c1', 9))).toBeNull();
    expect(applyCollection(stateWith([companion('c1', 9)]), { type: 'reincarnate', id: 'c1' })).toHaveProperty('error');
    const original = companion('c1', 10, 2);
    for (const patch of [{ id: 'c9' }, { speciesId: 'slime' }, { bossIndex: 15 }, { level: 11 }, { stars: 3 }]) {
      const changed = stateWith([{ ...original, ...patch }]), before = structuredClone(changed);
      expect(applyCollection(changed, { type: 'reincarnate', id: 'c1', expected: original })).toHaveProperty('error');
      expect(changed).toEqual(before);
    }
    const absent = stateWith([]);
    expect(applyCollection(absent, { type: 'reincarnate', id: 'c1', expected: original })).toHaveProperty('error');
    const action: CollectionAction = { type: 'reincarnate', id: 'c1', expected: original };
    const once = success(stateWith([original]), action), before = structuredClone(once);
    expect(applyCollection(once, action)).toHaveProperty('error');
    expect(once).toEqual(before);
  });

  it('validates confirmation snapshots at the trust boundary', () => {
    expect(isCompanionSnapshot(companion('c1', max))).toBe(true);
    for (const value of [null, {}, { ...companion('c1'), level: max + 1 },
      { ...companion('c1'), level: 0 }, { ...companion('c1'), stars: -1 },
      { ...companion('c1'), stars: 1.5 }, { ...companion('c1'), bossIndex: -1 },
      { ...companion('c1'), speciesId: '' }]) {
      expect(isCompanionSnapshot(value)).toBe(false);
      const state = stateWith([companion('c1')]), before = structuredClone(state);
      expect(applyCollection(state, { type: 'reincarnate', id: 'c1', expected: value } as CollectionAction)).toHaveProperty('error');
      expect(state).toEqual(before);
    }
  });

  it('preserves a sacrificed companion when the soul reward would overflow', () => {
    const state = { ...stateWith([companion('c1', 250)]), souls: max };
    const before = structuredClone(state);
    expect(applyCollection(state, { type: 'sacrifice', id: 'c1' })).toHaveProperty('error');
    expect(state).toEqual(before);
    const boundary = success({ ...state, souls: max - 1 }, { type: 'sacrifice', id: 'c1' });
    expect(boundary.souls).toBe(max);
    expect(boundary.companions).toEqual([]);
  });

  it('preserves server transfer IDs and rejects duplicate or conflicting delivery without any removal', () => {
    for (const id of ['s7', 'r0123abcd']) {
      const incoming = companion(id, 250);
      const base = stateWith([companion('c1')]);
      const action: CollectionAction = id.startsWith('s')
        ? { type: 'pvpResult', won: true, stolen: incoming, lostId: null }
        : { type: 'addCompanion', companion: incoming };
      const received = success(base, action), before = structuredClone(received);
      expect(received.companions).toEqual([companion('c1'), incoming]);
      expect(applyCollection(received, action)).toHaveProperty('error');
      expect(applyCollection(received, { type: 'pvpResult', won: true,
        stolen: { ...incoming, level: 251 }, lostId: 'c1' })).toHaveProperty('error');
      expect(received).toEqual(before);
    }
    // Internal legacy callers with local IDs retain collision-free local minting.
    const base = stateWith([companion('c1')]);
    expect(success(base, { type: 'addCompanion', companion: companion('c1', 250) }).companions)
      .toEqual([companion('c1'), companion('c2', 250)]);
  });
});

