import {
  conditionStatus, fieldPhase, FIELD_PHASE_MS, FIELD_PHASE_NAMES, rareHero, rareMonster,
} from '../core/discovery.js';
import type { DiscoveryContext, Requirement } from '../core/discovery.js';
import {
